begin;
    with j as (select * from jsonb_to_recordset($law7v003$[{"code_id":"APK_RF","article_number":"240.5","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о содействии арбитражный суд выносит определение по правилам, установленным главой 21 настоящего Кодекса для вынесения определения.\n\n2. В определении арбитражного суда по делу о выполнении арбитражными судами функций содействия в отношении третейских судов должны содержаться:\n\n1) наименование постоянно действующего арбитражного учреждения, администрирующего третейское разбирательство, его место нахождения (в случае наличия постоянно действующего арбитражного учреждения);\n\n2) сведения о составе третейского суда, рассматривающего спор, его месте нахождения;\n\n3) наименования сторон третейского разбирательства;\n\n4) изложение обстоятельств, являющихся основанием для обращения заявителя в арбитражный суд за содействием в отношении третейского суда, а также указание на нормы федерального закона, предусматривающие выполнение арбитражным судом тех функций, за выполнением которых обращается заявитель;\n\n5) указание на удовлетворение требований заявителя полностью или в части либо отказ в удовлетворении требований заявителя полностью или в части с указанием мотивов, по которым арбитражный суд удовлетворил требования заявителя или отказал в их удовлетворении;\n\n6) в случае удовлетворения требований заявителя сведения о третейском судье (третейских судьях), вопросы об отводе, о назначении или прекращении полномочий которого разрешены.\n\n3. Определение арбитражного суда по делу о выполнении арбитражными судами функций содействия в отношении третейского суда не может быть обжаловано.","article_title":"Статья 240.5. Определение арбитражного суда по делу о выполнении арбитражными судами функций содействия в отношении третейских судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91e179d2e476e6f070d52b7d6bd00486c0393dd5c0dd013b5919b8e448798cf6"},{"code_id":"APK_RF","article_number":"241","version_date":"2002-07-24","article_text":"1. Решения судов иностранных государств, принятые ими по спорам и иным делам, возникающим при осуществлении предпринимательской и иной экономической деятельности (иностранные суды), решения третейских судов и международных коммерческих арбитражей, принятые ими на территориях иностранных государств по спорам и иным делам, возникающим при осуществлении предпринимательской и иной экономической деятельности (иностранные арбитражные решения), признаются и приводятся в исполнение в Российской Федерации арбитражными судами, если признание и приведение в исполнение таких решений предусмотрено международным договором Российской Федерации и федеральным законом.\n\n2. Вопросы признания и приведения в исполнение решения иностранного суда и иностранного арбитражного решения разрешаются арбитражным судом по заявлению стороны в споре, рассмотренном иностранным судом, или стороны третейского разбирательства.","article_title":"Статья 241. Признание и приведение в исполнение решений иностранных судов и иностранных арбитражных решений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27b9336be0f68cbb03cddfae260525e4b880f6565bd8e5a2f454633232d30ebd"},{"code_id":"APK_RF","article_number":"242","version_date":"2002-07-24","article_text":"В заявлении должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование и место нахождения иностранного суда либо наименование и состав третейского суда или международного коммерческого арбитража, место его нахождения;\n\n3) наименование взыскателя, его место нахождения или место жительства;\n\n4) наименование должника, его место нахождения или место жительства;\n\n5) сведения о решении иностранного суда или об иностранном арбитражном решении, о признании и приведении в исполнение которых ходатайствует взыскатель;\n\n6) ходатайство взыскателя о признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения;\n\n7) перечень прилагаемых документов.\n\nВ заявлении о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения могут быть также указаны номера телефонов, факсов, адреса электронной почты взыскателя, должника, их представителей и иные сведения.\n\n1) удостоверенная надлежащим образом копия решения иностранного суда или иностранного арбитражного решения, о признании и приведении в исполнение которых ходатайствует взыскатель;\n\n2) документ, удостоверенный надлежащим образом и подтверждающий вступление решения иностранного суда в законную силу, если это не указано в тексте самого решения;\n\n3) документ, удостоверенный надлежащим образом и подтверждающий, что должник был своевременно и в надлежащей форме извещен о разбирательстве дела в иностранном суде, о признании и приведении в исполнение решения которого ходатайствует взыскатель;\n\n4) доверенность или иной документ, удостоверенные надлежащим образом и подтверждающие полномочия лица, подписавшего заявление в арбитражный суд;\n\n5) документ, подтверждающий направление должнику копии заявления о признании и приведении в исполнение решения иностранного суда;\n\n6) заверенный надлежащим образом перевод указанных в пунктах 1 - 5 настоящей части документов на русский язык.\n\n1) надлежащим образом заверенное подлинное иностранное арбитражное решение или его надлежащим образом заверенная копия;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия;\n\n3) надлежащим образом заверенный перевод на русский язык документов, указанных в пунктах 1 и 2 настоящей части.","article_title":"Статья 242. Заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"adecce77c95d08acb69b1b9d4a45d76d573b399569ec8decf34e3eb7f2967e4f"},{"code_id":"APK_RF","article_number":"243","version_date":"2002-07-24","article_text":"1. Заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящей главой, в срок, не превышающий одного месяца со дня его поступления в арбитражный суд субъекта Российской Федерации.\n\n2. Арбитражный суд извещает лиц, участвующих в деле, о времени и месте судебного заседания. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела.\n\n3. При рассмотрении дела арбитражный суд в судебном заседании устанавливает наличие или отсутствие оснований для признания и приведения в исполнение решения иностранного суда и иностранного арбитражного решения, предусмотренных статьей 244 настоящего Кодекса, путем исследования представленных в арбитражный суд доказательств, обоснования заявленных требований и возражений, а также разъяснений иностранного суда или третейского суда, принявших решение, если арбитражный суд истребует такие разъяснения.\n\n4. При рассмотрении дела арбитражный суд не вправе пересматривать решение иностранного суда по существу.\n\n5. Если в иностранном суде находится на рассмотрении заявление об отмене или о приостановлении исполнения решения иностранного суда и иностранного арбитражного решения, арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение этого решения, может по ходатайству одной из сторон отложить рассмотрение заявления о выдаче исполнительного листа.\n\n6. В случае, указанном в части 5 настоящей статьи, арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения, по ходатайству стороны, обратившейся с таким заявлением, может обязать другую сторону предоставить надлежащее обеспечение по правилам, предусмотренным настоящим Кодексом.\n\n7. Если в случае, указанном в части 5 настоящей статьи, рассмотрение заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения было отложено арбитражным судом, после разрешения иностранным судом заявления об отмене или о приостановлении исполнения решения иностранного суда и иностранного арбитражного решения арбитражный суд, в котором рассматривается заявление о признании и приведении в исполнение этого решения, рассматривает заявление о признании и приведении в исполнение этого решения с учетом вынесенного иностранным судом судебного акта в соответствии с международными договорами Российской Федерации и федеральными законами.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)","article_title":"Статья 243. Порядок рассмотрения заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7f594a489b6ad033b8a44a94781bde76c1f744a1b933997285dccdc807a8ece6"},{"code_id":"APK_RF","article_number":"244","version_date":"2002-07-24","article_text":"1. Арбитражный суд отказывает в признании и приведении в исполнение решения иностранного суда полностью или в части в случае, если:\n\n1) решение по закону государства, на территории которого оно принято, не вступило в законную силу;\n\n2) сторона, против которой принято решение, не была своевременно и надлежащим образом извещена о времени и месте рассмотрения дела или по другим причинам не могла представить в суд свои объяснения;\n\n3) рассмотрение дела в соответствии с международным договором Российской Федерации или федеральным законом относится к исключительной компетенции суда в Российской Федерации, за исключением случаев, указанных в части 5 статьи 2481 настоящего Кодекса; (В редакции Федерального закона от 08.06.2020 № 171-ФЗ)\n\n4) имеется вступившее в законную силу решение суда в Российской Федерации, принятое по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n5) на рассмотрении суда в Российской Федерации находится дело по спору между теми же лицами, о том же предмете и по тем же основаниям, производство по которому возбуждено до возбуждения производства по делу в иностранном суде, или суд в Российской Федерации первым принял к своему производству заявление по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n6) истек срок давности приведения решения иностранного суда к принудительному исполнению и этот срок не восстановлен арбитражным судом;\n\n7) исполнение решения иностранного суда противоречило бы публичному порядку Российской Федерации.","article_title":"Статья 244. Основания отказа в признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"974e5ae2e41dd57ee7a7c05aff99eb114705f4da4cae358f3b9ad90e10341615"},{"code_id":"APK_RF","article_number":"245","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения заявления о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения арбитражный суд выносит определение по правилам, установленным в главе 20 настоящего Кодекса для принятия решения.\n\n2. В определении по делу о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения должны содержаться:\n\n1) наименование и место нахождения иностранного суда либо наименование и состав третейского суда или международного коммерческого арбитража, принявших решение;\n\n2) наименования взыскателя и должника;\n\n3) сведения о решении иностранного суда или об иностранном арбитражном решении, о признании и приведении в исполнение которого ходатайствовал взыскатель;\n\n4) указание на признание и приведение в исполнение решения иностранного суда или иностранного арбитражного решения либо на отказ в признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения.","article_title":"Статья 245. Определение арбитражного суда по делу о признании и приведении в исполнение решения иностранного суда и иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ae0c8bc65b0bffee41412dcb9e7b2e4c53aa94cba47bd8c84cd823ddb694394"},{"code_id":"APK_RF","article_number":"245.1","version_date":"2002-07-24","article_text":"1. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения, признаются в Российской Федерации, если их признание предусмотрено международным договором Российской Федерации и федеральным законом.\n\n2. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения, признаются в Российской Федерации без какого-либо дальнейшего производства, если со стороны заинтересованного лица не поступят возражения относительно этого.\n\n3. Заинтересованное лицо в течение одного месяца после того, как ему стало известно о решении иностранного суда или об иностранном арбитражном решении, может заявить возражения относительно признания этого решения в арбитражный суд субъекта Российской Федерации по месту нахождения или месту жительства заинтересованного лица либо месту нахождения его имущества, а если заинтересованное лицо не имеет места жительства, места нахождения или имущества в Российской Федерации, в Арбитражный суд города Москвы.\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование и место нахождения иностранного суда либо состав третейского суда или международного коммерческого арбитража, его место нахождения;\n\n3) наименование заинтересованного лица, его место нахождения или место жительства;\n\n4) сведения о решении иностранного суда или об иностранном арбитражном решении, возражения против признания которых заявляет заинтересованное лицо;\n\n5) ходатайство заинтересованного лица об отказе в признании решения иностранного суда или иностранного арбитражного решения с приведением оснований для отказа в таком признании, а также с обоснованием нарушения указанным решением прав и законных интересов заинтересованного лица в сфере предпринимательской и иной экономической деятельности в Российской Федерации;\n\n6) перечень прилагаемых документов.\n\n1) удостоверенная надлежащим образом копия решения иностранного суда или иностранного арбитражного решения, возражения против признания которых заявляет заинтересованное лицо;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия, если заинтересованным лицом заявляются возражения против признания иностранного арбитражного решения;\n\n3) доверенность или иной документ, удостоверенные надлежащим образом и подтверждающие полномочия лица, подписавшего заявление в арбитражный суд;\n\n4) документ об уплате государственной пошлины за подачу заявления в размере, предусмотренном федеральным законом для оплаты искового заявления неимущественного характера;\n\n5) заверенный надлежащим образом перевод на русский язык документов, указанных в пунктах 1 - 3 настоящей части.\n\n(Дополнение статьей - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 245.1. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e0d440a65ed6970189f383284fce86cc65d166f0026e43a2388034a9c71102a"},{"code_id":"APK_RF","article_number":"246","version_date":"2002-07-24","article_text":"1. Принудительное исполнение решения иностранного суда или иностранного арбитражного решения производится на основании исполнительного листа, выдаваемого арбитражным судом, вынесшим определение о признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения, в порядке, предусмотренном настоящим Кодексом и федеральным законом об исполнительном производстве.\n\n2. Решение иностранного суда или иностранное арбитражное решение может быть предъявлено к принудительному исполнению в срок, не превышающий трех лет со дня вступления его в законную силу. В случае пропуска указанного срока он может быть восстановлен арбитражным судом по ходатайству взыскателя по правилам, предусмотренным главой 10 настоящего Кодекса.\n\nРАЗДЕЛ V. ПРОИЗВОДСТВО ПО ДЕЛАМ С УЧАСТИЕМ ИНОСТРАННЫХ ЛИЦ","article_title":"Статья 246. Принудительное исполнение решения иностранного суда или иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd1cd33d2887283fbe8a3d9a42bc43f22b4612e7147b191262766073bf5db107"},{"code_id":"APK_RF","article_number":"247","version_date":"2002-07-24","article_text":"1. Арбитражные суды в Российской Федерации рассматривают дела по экономическим спорам и другие дела, связанные с осуществлением предпринимательской и иной экономической деятельности, с участием иностранных организаций, международных организаций, иностранных граждан, лиц без гражданства, осуществляющих предпринимательскую и иную экономическую деятельность (далее - иностранные лица), в случае, если:\n\n1) ответчик находится или проживает на территории Российской Федерации либо на территории Российской Федерации находится имущество ответчика;\n\n2) орган управления, филиал или представительство иностранного лица находится на территории Российской Федерации;\n\n3) спор возник из договора, по которому исполнение должно иметь место или имело место на территории Российской Федерации;\n\n4) требование возникло из причинения вреда имуществу действием или иным обстоятельством, имевшими место на территории Российской Федерации или при наступлении вреда на территории Российской Федерации;\n\n5) спор возник из неосновательного обогащения, имевшего место на территории Российской Федерации;\n\n6) истец по делу о защите деловой репутации находится в Российской Федерации;\n\n7) спор возник из отношений, связанных с обращением ценных бумаг, выпуск которых имел место на территории Российской Федерации;\n\n8) заявитель по делу об установлении факта, имеющего юридическое значение, указывает на наличие этого факта на территории Российской Федерации;\n\n9) спор возник из отношений, связанных с государственной регистрацией имен и других объектов и оказанием услуг в международной ассоциации информационно-телекоммуникационных сетей \"Интернет\" на территории Российской Федерации; (В редакции Федерального закона от 11.07.2011 № 200-ФЗ)\n\n10) в других случаях при наличии тесной связи спорного правоотношения с территорией Российской Федерации.","article_title":"Статья 247. Компетенция арбитражных судов в Российской Федерации по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5df1a1ca11f2f9576ed3bd740e822b2b5f4db955e45c02b945d4b43926aba049"},{"code_id":"APK_RF","article_number":"248","version_date":"2002-07-24","article_text":"1. К исключительной компетенции арбитражных судов в Российской Федерации по делам с участием иностранных лиц относятся дела:\n\n1) по спорам в отношении находящегося в государственной собственности Российской Федерации имущества, в том числе по спорам, связанным с приватизацией государственного имущества и принудительным отчуждением имущества для государственных нужд;\n\n2) по спорам, предметом которых являются недвижимое имущество, если такое имущество находится на территории Российской Федерации, или права на него;\n\n3) по спорам, связанным с регистрацией или выдачей патентов, регистрацией и выдачей свидетельств на товарные знаки, промышленные образцы, полезные модели или регистрацией других прав на результаты интеллектуальной деятельности, которые требуют регистрации или выдачи патента либо свидетельства в Российской Федерации;\n\n4) по спорам о признании недействительными записей в государственные реестры (регистры, кадастры), произведенных компетентным органом Российской Федерации, ведущим такой реестр (регистр, кадастр);\n\n5) по спорам, связанным с учреждением, ликвидацией или регистрацией на территории Российской Федерации юридических лиц и индивидуальных предпринимателей, а также с оспариванием решений органов этих юридических лиц.\n\n2. В исключительной компетенции арбитражных судов в Российской Федера\n\nции находятся также предусмотренные в разделе III настоящего Кодекса дела с участием иностранных лиц, возникающие из административных и иных публичных правоотношений.","article_title":"Статья 248. Исключительная компетенция арбитражных судов в Российской Федерации по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e4b4e4a746f28603987ea851b550ff1766a3361b1b6f22afcfd2332b91e7a2a"},{"code_id":"APK_RF","article_number":"248.1","version_date":"2002-07-24","article_text":"1. Если иное не установлено международным договором Российской Федерации или соглашением сторон, в соответствии с которыми рассмотрение споров с их участием отнесено к компетенции иностранных судов, международных коммерческих арбитражей, находящихся за пределами территории Российской Федерации, к исключительной компетенции арбитражных судов в Российской Федерации относятся дела:\n\n1) по спорам с участием лиц, в отношении которых применяются меры ограничительного характера иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза;\n\n2) по спорам одного российского или иностранного лица с другим российским или иностранным лицом, если основанием для таких споров являются ограничительные меры, введенные иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза в отношении граждан Российской Федерации и российских юридических лиц.\n\n2. В целях настоящей главы к лицам, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера, относятся:\n\n1) граждане Российской Федерации, российские юридические лица, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера;\n\n2) иностранные юридические лица, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера и основанием для применения таких мер являются ограничительные меры, введенные иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза в отношении граждан Российской Федерации и российских юридических лиц.\n\n3. Лица, указанные в части 2 настоящей статьи, вправе:\n\n1) обратиться за разрешением спора в арбитражный суд субъекта Российской Федерации по месту своего нахождения или месту жительства при условии, что в производстве иностранного суда или международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, отсутствует спор между теми же лицами, о том же предмете и по тем же основаниям;\n\n2) обратиться в порядке, предусмотренном статьей 2482 настоящего Кодекса, с заявлением о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации.\n\n4. Положения настоящей статьи применяются также в случае, если соглашение сторон, в соответствии с которым рассмотрение споров с их участием отнесено к компетенции иностранного суда и международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, неисполнимо по причине применения в отношении одного из лиц, участвующих в споре, мер ограничительного характера иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза, создающих такому лицу препятствия в доступе к правосудию.\n\n5. Положения настоящей статьи не препятствуют признанию и приведению в исполнение решения иностранного суда или иностранного арбитражного решения, принятых по иску лица, указанного в части 2 настоящей статьи, либо если это лицо не возражало против рассмотрения с его участием спора иностранным судом, международным коммерческим арбитражем, находящимися за пределами территории Российской Федерации, в том числе не обращалось с заявлением о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 08.06.2020 № 171-ФЗ)","article_title":"Статья 248.1. Исключительная компетенция арбитражных судов в Российской Федерации по спорам с участием лиц, в отношении которых введены меры ограничительного характера","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89619448462f5685ffa7c892e03e6cd95ede6e9015a3ac1c4b1aed8b842858a3"},{"code_id":"APK_RF","article_number":"248.2","version_date":"2002-07-24","article_text":"1. Лицо, в отношении которого инициировано разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, по спорам, указанным в статье 2481 настоящего Кодекса, или при наличии доказательств того, что такое разбирательство будет инициировано, вправе обратиться в арбитражный суд субъекта Российской Федерации по месту своего нахождения или месту жительства с заявлением о запрете инициировать или продолжать такое разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, в порядке, установленном настоящей статьей.\n\n2. В заявлении, предусмотренном частью 1 настоящей статьи, должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование заявителя, его адрес или место жительства, а также наименование лица, в отношении которого требуется установить запрет, его адрес или место жительства;\n\n3) сведения о требованиях, которые могут быть предъявлены или уже предъявлены в иностранном суде, международном коммерческом арбитраже;\n\n4) обстоятельства, подтверждающие исключительную компетенцию арбитражных судов в Российской Федерации по рассмотрению спора, в том числе обстоятельства (при их наличии), подтверждающие, что соглашение сторон, в соответствии с которым рассмотрение спора с их участием отнесено к компетенции иностранного суда, международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, не может быть исполнено стороной спора;\n\n5) требование заявителя о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации;\n\n6) перечень прилагаемых документов.\n\n3. В заявлении, предусмотренном частью 1 настоящей статьи, могут быть также указаны номера телефонов, факсов, адреса электронной почты заявителя и лиц, которые могут инициировать или инициировали разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, а также их представителей.\n\n4. К заявлению, предусмотренному частью 1 настоящей статьи, прилагаются:\n\n1) копии документов, подтверждающих намерение инициировать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо факт начала разбирательства в иностранном суде, международном коммерческом арбитраже, в том числе претензии, требования, иски и иные документы;\n\n2) копии документов, подтверждающих исключительную компетенцию арбитражных судов в Российской Федерации по рассмотрению спора;\n\n3) иные документы, указанные в статье 126 настоящего Кодекса.\n\n5. Заявление, предусмотренное частью 1 настоящей статьи, рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящей статьей.\n\n6. Арбитражный суд извещает лиц, участвующих в деле, о времени и месте судебного заседания в порядке, установленном настоящим Кодексом. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения заявления, предусмотренного частью 1 настоящей статьи.\n\n7. По результатам рассмотрения заявления, предусмотренного частью 1 настоящей статьи, арбитражный суд выносит определение по правилам, установленным главой 20 настоящего Кодекса для вынесения решений.\n\n8. В определении о запрете или об отказе в запрете стороне инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, должны содержаться:\n\n1) наименования заявителя и лица, в отношении которого выносится запрет;\n\n2) сведения о требованиях, которые могут быть предъявлены в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо сведения о конкретном разбирательстве в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, в отношении которых устанавливается запрет;\n\n3) указание на удовлетворение заявления о запрете лицу инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо на отказ в удовлетворении такого заявления.\n\n9. Определение арбитражного суда по делу о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, по спорам, указанным в статье 2481 настоящего Кодекса, может быть обжаловано в кассационном порядке в арбитражный суд округа в течение одного месяца со дня вынесения определения.\n\n10. Арбитражный суд на основе принципов справедливости, соразмерности и недопустимости извлечения выгоды из незаконного или недобросовестного поведения по требованию заявителя вправе присудить в его пользу денежную сумму, подлежащую взысканию с лица, в отношении которого вынесен запрет инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, на случай неисполнения им судебного акта. Размер подлежащей взысканию арбитражным судом денежной суммы не должен превышать размера исковых требований, предъявленных в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, и понесенных стороной спора судебных расходов.\n\n(Дополнение статьей - Федеральный закон от 08.06.2020 № 171-ФЗ)","article_title":"Статья 248.2. Запрет инициировать или продолжать разбирательство по спорам с участием лиц, в отношении которых введены меры ограничительного характера","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"de43cb8183e021278fbda594cdc308bf387e7401391d5a81d03066903d401098"},{"code_id":"APK_RF","article_number":"249","version_date":"2002-07-24","article_text":"1. В случае, если стороны, хотя бы одна из которых является иностранным лицом, заключили соглашение, в котором определили, что арбитражный суд в Российской Федерации обладает компетенцией по рассмотрению возникшего или могущего возникнуть спора, связанного с осуществлением ими предпринимательской и иной экономической деятельности, арбитражный суд в Российской Федерации будет обладать исключительной компетенцией по рассмотрению данного спора при условии, что такое соглашение не изменяет исключительную компетенцию иностранного суда.\n\n2. Соглашение об определении компетенции должно быть заключено в письменной форме.","article_title":"Статья 249. Соглашение об определении компетенции арбитражных судов в Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"822279f33f68075e471e834a76a55f8d2348c6952a37761828c4b6000a0f195c"},{"code_id":"APK_RF","article_number":"25","version_date":"2002-07-24","article_text":"1. В случае заявления отвода арбитражный суд заслушивает мнение лиц, участвующих в деле, а также лица, которому заявлен отвод, если отводимый желает дать объяснения.\n\n2. Вопрос об отводе судьи, рассматривающего дело единолично, разрешается тем же судьей.\n\n3. Вопрос об отводе судьи при рассмотрении дела в коллегиальном составе разрешается этим же составом суда большинством голосов в отсутствие судьи, которому заявлен отвод. При равном числе голосов, поданных за отвод и против отвода, судья считается отведенным.\n\nВопрос об отводе, заявленном нескольким судьям или всему рассматривающему дело составу суда, разрешается всеми судьями, рассматривающими дело, простым большинством голосов.\n\n4. Вопрос об отводе помощника судьи, секретаря судебного заседания, эксперта, специалиста, переводчика разрешается составом суда, рассматривающим дело.\n\n5. По результатам рассмотрения вопроса о самоотводе или об отводе выносится определение.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 25. Порядок разрешения заявленного отвода","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8dbb8fb742e71b9f023f2e9eb2cb064683900e25891c8f41a29926c2d3f9daaa"},{"code_id":"APK_RF","article_number":"250","version_date":"2002-07-24","article_text":"По делам с участием иностранных лиц, отнесенным к компетенции арбитражных судов в Российской Федерации в соответствии с главой 32 настоящего Кодекса, арбитражный суд в Российской Федерации может принять обеспечительные меры по правилам главы 8 настоящего Кодекса.","article_title":"Статья 250. Компетенция арбитражных судов в Российской Федерации по применению обеспечительных мер по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f159c0864cb97e4d99984b4a90e1b9ca7c70d2f3b0ff885494c7af5bec10497"},{"code_id":"APK_RF","article_number":"251","version_date":"2002-07-24","article_text":"1. Судебный иммунитет международных организаций определяется международным договором Российской Федерации, федеральным законом.\n\n2. Отказ от судебного иммунитета должен быть произведен в порядке, предусмотренном правилами международной организации. В этом случае арбитражный суд рассматривает дело в порядке, установленном настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 393-ФЗ)","article_title":"Статья 251. Судебный иммунитет международных организаций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c20ee20849217589f660fa627e15ffd761cbc8c844c62ed53f1796a69671c8b2"},{"code_id":"APK_RF","article_number":"253","version_date":"2002-07-24","article_text":"1. Дела с участием иностранных лиц рассматриваются арбитражным судом по правилам настоящего Кодекса с особенностями, предусмотренными настоящей главой, если международным договором Российской Федерации не предусмотрено иное.\n\n2. Дела с участием иностранных лиц, если эти лица или их органы управления, филиалы, представительства либо их представители, уполномоченные на ведение дела, находятся или проживают на территории Российской Федерации, рассматриваются в сроки, установленные настоящим Кодексом.","article_title":"Статья 253. Порядок рассмотрения дел с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7cb927f1ab46aea9390aecfac7b9ccf6911bef5f90de25f7c466c5cfb07e1a1"},{"code_id":"APK_RF","article_number":"254","version_date":"2002-07-24","article_text":"1. Иностранные лица пользуются процессуальными правами и несут процессуальные обязанности наравне с российскими организациями и гражданами. Процессуальные льготы предоставляются иностранным лицам, если они предусмотрены международным договором Российской Федерации.\n\nВ случае непредставления таких доказательств арбитражный суд вправе истребовать их по своей инициативе.","article_title":"Статья 254. Процессуальные права и обязанности иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"54a55db864f33fd2f7635a860dad2b1789133363d2d6147989b906cb6cbbe701"},{"code_id":"APK_RF","article_number":"255","version_date":"2002-07-24","article_text":"1. Документы, выданные, составленные или удостоверенные по установленной форме компетентными органами иностранных государств вне пределов Российской Федерации по нормам иностранного права в отношении российских организаций и граждан или иностранных лиц, принимаются арбитражными судами в Российской Федерации при наличии легализации указанных документов или проставлении апостиля, если иное не установлено международным договором Российской Федерации.\n\n2. Документы, составленные на иностранном языке, при представлении в арбитражный суд в Российской Федерации должны сопровождаться их надлежащим образом заверенным переводом на русский язык.","article_title":"Статья 255. Требования, предъявляемые к документам иностранного происхождения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02ac110070ec140f2e5393f78025eb6486b07a48d76863475b2d7b6956322e74"},{"code_id":"APK_RF","article_number":"256","version_date":"2002-07-24","article_text":"1. Арбитражный суд исполняет переданные ему в порядке, установленном международным договором Российской Федерации или федеральным законом, поручения иностранных судов и компетентных органов иностранных государств о выполнении отдельных процессуальных действий (вручение повесток и других документов, получение письменных доказательств, производство экспертизы, осмотр на месте и другие).\n\n2. Поручение иностранного суда или компетентного органа иностранного государства не подлежит исполнению, если:\n\n1) исполнение поручения нарушает основополагающие принципы российского права или иным образом противоречит публичному порядку Российской Федерации;\n\n2) исполнение поручения не относится к компетенции арбитражного суда в Российской Федерации;\n\n3) не установлена подлинность документа, содержащего поручение о выполнении отдельных процессуальных действий.\n\n3. Исполнение арбитражным судом поручений о выполнении отдельных процессуальных действий производится в порядке, установленном настоящим Кодексом, если иное не предусмотрено международным договором Российской Федерации.\n\n4. Арбитражные суды могут в порядке, установленном международным договором Российской Федерации или федеральным законом, обращаться к иностранным судам или компетентным органам иностранных государств с поручениями о выполнении отдельных процессуальных действий.\n\n(Дополнение главой - Федеральный закон от 29.12.2015 № 393-ФЗ)","article_title":"Статья 256. Поручения о выполнении отдельных процессуальных действий","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"decb690ad63302ee7c457d55b165b305cc8bc40a090e41afca5e8d903092dbf3"},{"code_id":"APK_RF","article_number":"256.1","version_date":"2002-07-24","article_text":"1. Предъявление в арбитражном суде иска к иностранному государству, привлечение иностранного государства к участию в деле в качестве ответчика или третьего лица, наложение ареста на имущество иностранного государства, находящееся на территории Российской Федерации, принятие в отношении этого имущества иных мер по обеспечению иска, обращение взыскания на это имущество в порядке исполнения решений арбитражного суда, а также рассмотрение заявлений о признании и принудительном исполнении решений иностранных судов в отношении имущества иностранного государства, находящегося на территории Российской Федерации, осуществляется в соответствии с Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\" в порядке, установленном настоящим Кодексом, если иное не предусмотрено международным договором Российской Федерации.\n\n2. Дела с участием иностранного государства рассматриваются по общим правилам искового производства с особенностями, установленными настоящей главой, главами 32 и 33 настоящего Кодекса и другими федеральными законами\n\n. Заявления о признании и принудительном исполнении решений иностранных судов в отношении имущества иностранного государства, находящегося на территории Российской Федерации, рассматриваются в порядке, установленном настоящей главой, главой 31 настоящего Кодекса и другими федеральными законами.\n\n3. Для целей настоящего Кодекса понятие \"иностранное государство\" используется в значении, определяемом Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\".","article_title":"Статья 256.1. Производство по делам с участием иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96efc922387771d212bad95e0fa8cc7d7cee41a5898fa27fe879a3c0049cde5a"},{"code_id":"APK_RF","article_number":"256.10","version_date":"2002-07-24","article_text":"1. Арбитражный суд вправе рассмотреть дело в отсутствие представителя иностранного государства, являющегося ответчиком по делу, в случае его неявки без уважительных причин в судебное заседание при соблюдении следующих условий:\n\n1) иностранное государство в соответствии с требованиями статьи 2566 настоящего Кодекса надлежащим образом извещено о принятии искового заявления к производству, о возбуждении производства по делу, а также о времени и месте судебного заседания;\n\n2) со дня вручения иностранному государству извещения о возбуждении против него дела прошло не менее шести месяцев;\n\n3) иностранным государством не заявлено ходатайство об отложении на разумный срок судебного заседания либо указанное ходатайство мотивированно отклонено судом.\n\n2. По результатам рассмотрения дела в отсутствие иностранного государства, являющегося ответчиком по делу, и при соблюдении всех условий, предусмотренных частью 1 настоящей статьи, арбитражный суд может вынести решение в отсутствие указанного иностранного государства, если установит, что в соответствии с законодательством Российской Федерации иностранное государство не пользуется судебным иммунитетом в отношении рассматриваемого спора. Копия решения арбитражного суда не позднее чем в течение пяти дней со дня его принятия направляется арбитражным судом иностранному государству в порядке, установленном статьей 256 настоящего Кодекса.\n\n3. Иностранное государство в течение двух месяцев со дня вручения ему в порядке, установленном статьей 256 настоящего Кодекса, копии указанного в части 2 настоящей статьи решения арбитражного суда вправе подать в арбитражный суд, принявший такое решение, заявление о его отмене.\n\n4. Решение арбитражного суда, вынесенное по результатам рассмотрения дела в отсутствие иностранного государства, являющегося ответчиком по делу, также может быть обжаловано сторонами в апелляционном порядке в течение месяца после истечения срока подачи ответчиком заявления об отмене этого решения арбитражного суда, а в случае, если такое заявление подано, - в течение двух месяцев со дня вынесения арбитражным судом определения об отказе в удовлетворении этого заявления.","article_title":"Статья 256.10. Рассмотрение дела в отсутствие иностранного государства, являющегося ответчиком","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93f5190acb1a8d20dfd4f0fd4e5dd038dc12fbca90ca47e6916f26a7c3cf18cd"},{"code_id":"APK_RF","article_number":"256.11","version_date":"2002-07-24","article_text":"1. При рассмотрении арбитражным судом дела с участием иностранного государства на это иностранное государство не может быть наложен судебный штраф, а также к этому иностранному государству не могут быть предъявлены требования о предварительной оплате судебных расходов, связанных с рассмотрением дела.\n\n2. Положения части 1 настоящей статьи не препятствуют арбитражному суду взыскать с иностранного государства судебные расходы по правилам, установленным главой 9 настоящего Кодекса, при принятии арбитражным судом решения по результатам рассмотрения дела по существу.","article_title":"Статья 256.11. Привилегии и иммунитеты иностранного государства в ходе судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"074ab854155a6187ec42d5577b7ba81e123bdf714d4121b84233a3b3e29376d7"},{"code_id":"APK_RF","article_number":"256.12","version_date":"2002-07-24","article_text":"Исполнение судебных актов арбитражного суда, вынесенных в отношении иностранного государства, его имущества, находящегося на территории Российской Федерации, по результатам рассмотрения соответствующих иска или заявления о признании и исполнении судебных решений другого иностранного государства, осуществляется в соответствии с законодательством Российской Федерации об исполнительном производстве. Исполнительный лист с копией судебного акта арбитражного суда направляется главному судебному приставу Российской Федерации. Одновременно арбитражный суд в порядке, установленном статьей 2566 настоящего Кодекса, извещает иностранное государство о вступлении судебного акта в законную силу и направлении исполнительных документов главному судебному приставу Российской Федерации для исполнения.\n\nРАЗДЕЛ VI. ПРОИЗВОДСТВО ПО ПЕРЕСМОТРУ СУДЕБНЫХ АКТОВ АРБИТРАЖНЫХ СУДОВ","article_title":"Статья 256.12. Порядок исполнения судебных актов арбитражного суда в отношении иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c179284449c81977d6a5e817707645cab975454b9b46e05b1f0190826cfc5e3"},{"code_id":"APK_RF","article_number":"256.2","version_date":"2002-07-24","article_text":"Компетенция судов Российской Федерации по рассмотрению дел с участием иностранного государства определяется по правилам, установленным главой 4 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 256.2. Компетенция арбитражных судов по делам с участием иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"311d28362c90e67be9b6ec8e99e6889a3febe3059f29cd3322236bacd6f342bc"},{"code_id":"APK_RF","article_number":"256.3","version_date":"2002-07-24","article_text":"1. Иностранное государство пользуется в отношении себя и своего имущества, находящегося на территории Российской Федерации, юрисдикционными иммунитетами с учетом положений Федерального закона от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\".\n\n2. Иностранное государство пользуется процессуальными правами и выполняет процессуальные обязанности наравне с российскими гражданами и организациями, в том числе правом вести свои дела в суде через представителей. Полномочия представителя иностранного государства должны быть выражены в доверенности или ином соответствующем документе, выданном представляемым иностранным государством и оформленном в соответствии с законодательством Российской Федерации или законодательством иностранного государства, с учетом требований, предусмотренных статьей 255 настоящего Кодекса.\n\n3. Представитель иностранного государства вправе совершать от имени представляемого им иностранного государства все процессуальные действия, за исключением действий, указанных в части 4 настоящей статьи, если иное не предусмотрено в доверенности или ином соответствующем документе, выданном представляемым иностранным государством.\n\n4. В доверенности или ином соответствующем документе, выданном представляемым иностранным государством, должно быть специально оговорено право представителя этого иностранного государства на подписание отзыва на исковое заявление, признание иска, отказа от судебного иммунитета, иммунитета в отношении мер по обеспечению иска, иммунитета в отношении исполнения судебного решения, предъявление встречного иска, изменение основания или предмета встречного иска, заключение мирового соглашения и соглашения по фактическим обстоятельствам, передачу своих полномочий представителя другому лицу (передоверие), получение судебных извещений (включая копии судебных актов), обжалование судебных актов, подписание, подачу заявления о пересмотре судебных актов по новым или вновь открывшимся обстоятельствам, а также на получение присужденных денежных средств или иного имущества.","article_title":"Статья 256.3. Юрисдикционные иммунитеты, процессуальные права и обязанности иностранного государства, представительство","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24ad692e4146097559688831051c6c184464eee7e846f06cdae6280810c8a2b4"},{"code_id":"APK_RF","article_number":"256.4","version_date":"2002-07-24","article_text":"1. Исковое заявление по спору с иностранным государством и прилагаемые к нему документы должны соответствовать требованиям статей 125 и 126 настоящего Кодекса и подаются в арбитражный суд с копиями искового заявления и прилагаемых к нему документов в соответствии с количеством ответчиков и третьих лиц.\n\n2. К исковому заявлению также прилагается надлежащим образом заверенный перевод искового заявления и прилагаемых к нему документов на официальный язык или один из официальных языков иностранного государства, привлекаемого к участию в деле.","article_title":"Статья 256.4. Подача искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ea5a9ad1e792ce664b6f071a00bb2b47ad1af09ba5f792554128842e7a1621e"},{"code_id":"APK_RF","article_number":"256.5","version_date":"2002-07-24","article_text":"1. Меры по обеспечению иска применяются арбитражным судом по заявлению лиц, участвующих в деле, в порядке, установленном главой 8 настоящего Кодекса, за исключением случаев, если иностранное государство и его имущество, находящееся на территории Российской Федерации, пользуются иммунитетом в отношении мер по обеспечению иска и иностранное государство не отказалось от этого иммунитета.\n\n2. Примененные арбитражным судом меры по обеспечению иска подлежат отмене, если в ходе судебного разбирательства будет установлено, что иностранное государство и его имущество, находящееся на территории Российской Федерации, пользуются иммунитетом в отношении мер по обеспечению иска или иммунитетом в отношении исполнения судебного решения и иностранное государство не отказалось от этих иммунитетов.","article_title":"Статья 256.5. Особенности применения мер по обеспечению иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bece0210f1fc999f16fcb3ce664b9f273496ec542abdbdc70d7b6a9b5b75ba22"},{"code_id":"APK_RF","article_number":"256.6","version_date":"2002-07-24","article_text":"1. Направление иностранному государству судебного извещения о возбуждении против него дела в суде Российской Федерации, а также иного процессуального документа, подлежащего вручению иностранному государству (далее - судебное извещение), осуществляется арбитражным судом в соответствии с применимым международным договором Российской Федерации.\n\n2. В случае отсутствия применимого международного договора Российской Федерации арбитражный суд направляет судебное извещение в федеральный орган исполнительной власти, уполномоченный в области юстиции, для последующего направления (вручения) иностранному государству по дипломатическим каналам через федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере международных отношений Российской Федерации.\n\n3. Заверенная копия дипломатической ноты, препровождающей направление судебного извещения иностранному государству, с указанием даты ее получения компетентным органом иностранного государства, ведающим вопросами иностранных дел, направляется в арбитражный суд, направивший извещение. Дата получения указанной дипломатической ноты компетентным органом иностранного государства, ведающим вопросами иностранных дел, считается датой вручения судебного извещения.\n\n4. Поступившие в Российскую Федерацию от иностранного государства по дипломатическим каналам отзыв, заявление, ходатайство и иные документы, касающиеся предъявленного к этому иностранному государству иска, направляются федеральным органом исполнительной власти, уполномоченным в области юстиции, в арбитражный суд, в производстве которого находится дело по иску к указанному иностранному государству.\n\n5. Указанные в частях 1 - 3 настоящей статьи судебные извещения могут быть вручены арбитражным судом непосредственно под расписку представителю иностранного государства, если он участвует в деле и в установленном порядке наделен соответствующими полномочиями.\n\n6. Судебные извещения о назначении предварительного судебного заседания или о назначении дела к разбирательству в судебном заседании направляются иностранному государству в порядке, установленном настоящей статьей, не позднее чем за шесть месяцев до дня судебного заседания.\n\n7. Судебные извещения, подлежащие вручению иностранному государству, составляются в двух экземплярах, заверяются судом и сопровождаются надлежащим образом заверенным переводом на официальный язык или один из официальных языков иностранного государства, привлекаемого к участию в деле.","article_title":"Статья 256.6. Направление и вручение иностранному государству извещений и иных процессуальных документов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22695dd3199d5b3924d3168155f7717611540920fcfaef17a34c433be98cf1af"},{"code_id":"APK_RF","article_number":"256.7","version_date":"2002-07-24","article_text":"1. В предварительном судебном заседании, проводимом в соответствии со статьей 136 настоящего Кодекса, арбитражный суд с участием сторон также решает вопрос о наличии у иностранного государства судебного иммунитета в отношении рассматриваемого спора.\n\n2. В случае неявки надлежащим образом извещенного о дате, времени и месте предварительного судебного заседания представителя иностранного государства суд принимает решение на основе материалов, имеющихся в деле.\n\n3. Если имеющиеся в деле материалы не позволяют арбитражному суду в предварительном судебном заседании сделать вывод о наличии у иностранного государства судебного иммунитета в отношении рассматриваемого спора, этот вопрос подлежит разрешению при разбирательстве в судебном заседании при рассмотрении дела.\n\n4. Установленные арбитражным судом обстоятельства и вывод арбитражного суда о наличии или отсутствии у иностранного государства судебного иммунитета, иммунитета в отношении мер по обеспечению иска и иммунитета в отношении исполнения решения суда должны быть отражены в судебном акте, принимаемом по результатам рассмотрения дела.\n\n5. В случае, если суд в предварительном судебном заседании или при разбирательстве в судебном заседании пришел к выводу о наличии у иностранного государства судебного иммунитета, суд прекращает производство по делу в отношении его.","article_title":"Статья 256.7. Особенности предварительного судебного заседания и прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16c94f03b893b1bceeb3abbb29482a0ae4bebbd5fb6aa7439c6fa8f989188423"},{"code_id":"APK_RF","article_number":"256.8","version_date":"2002-07-24","article_text":"1. Федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере международных отношений Российской Федерации, по инициативе суда или по собственной инициативе может участвовать в деле для дачи заключения по вопросам предоставления юрисдикционных иммунитетов Российской Федерации и ее имуществу в иностранном государстве.\n\n2. Заключение указанного в части 1 настоящей статьи федерального органа исполнительной власти может быть получено по вопросам о статусе образования, органа, организации, должностного лица, привлекаемых к участию в деле в качестве иностранного государства, о наличии судебного иммунитета в отношении рассматриваемого спора, иммунитета имущества иностранного государства, находящегося на территории Российской Федерации и являющегося предметом спора, иммунитета в отношении мер по обеспечению иска и иммунитета в отношении исполнения решения суда, о юрисдикционных иммунитетах, предоставляемых Российской Федерации в иностранном государстве, и их объеме, а также по иным вопросам, относящимся к компетенции указанного государственного органа.\n\n3. Заключение указанного в части 1 настоящей статьи федерального органа исполнительной власти подлежит оценке судом по установленным настоящим Кодексом правилам оценки доказательств.","article_title":"Статья 256.8. Участие в деле государственных органов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ddd185007ed5d8d8be6b191260440e48105a3c036217e216f51b29b44f4fb53c"},{"code_id":"APK_RF","article_number":"256.9","version_date":"2002-07-24","article_text":"1. При рассмотрении иска арбитражный суд по собственной инициативе или по ходатайству стороны в соответствии с Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\" может применить принцип взаимности, если в ходе судебного разбирательства будет установлено, что объем юрисдикционных иммунитетов, предоставляемых Российской Федерации в иностранном государстве, не соответствует объему юрисдикционных иммунитетов, предоставляемых этому иностранному государству в соответствии с законодательством Российской Федерации при разрешении конкретного спора.\n\n2. Соотношение объема юрисдикционных иммунитетов, предоставляемых Российской Федерации в иностранном государстве, и юрисдикционных иммунитетов иностранного государства в Российской Федерации определяется арбитражным судом на основании доказательств, представленных сторонами, и заключений государственных органов.\n\n3. Мотивированное решение арбитражного суда о применении принципа взаимности и в соответствии с ним ограничении юрисдикционных иммунитетов иностранного государства при рассмотрении конкретного дела указывается в решении арбитражного суда, принимаемом по итогам рассмотрения этого дела.","article_title":"Статья 256.9. Применение принципа взаимности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"866a3983605c7cef57cb02c183bd30dc95263e6457e0276e79bdb6ab49106347"},{"code_id":"APK_RF","article_number":"257","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, а также иные лица в случаях, предусмотренных настоящим Кодексом, вправе обжаловать в порядке апелляционного производства решение арбитражного суда первой инстанции, не вступившее в законную силу.","article_title":"Статья 257. Право апелляционного обжалования","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77de8803ff56fd30fced12be2b30f9901406bb28e472c1f69eede4a623ae6eb0"},{"code_id":"APK_RF","article_number":"258","version_date":"2002-07-24","article_text":"Апелляционные жалобы рассматривает в порядке апелляционного производства арбитражный суд апелляционной инстанции, образованный в соответствии с Федеральным конституционным законом \"Об арбитражных судах в Российской Федерации\".","article_title":"Статья 258. Арбитражный суд апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17969d1308607b0181b28a9471b035d901c7f7cadaa1dffc01f18e9f1be24cc4"},{"code_id":"APK_RF","article_number":"259","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба может быть подана в течение месяца после принятия арбитражным судом первой инстанции обжалуемого решения, если иной срок не установлен настоящим Кодексом.","article_title":"Статья 259. Срок подачи апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c58567a0bdec3495f012993b814187288dd4fd61ca81d6275ccebb2ad13d21f7"},{"code_id":"APK_RF","article_number":"26","version_date":"2002-07-24","article_text":"1. Судья, заявивший самоотвод, а также судья, в отношении которого удовлетворено заявление об отводе, заменяется другим судьей.\n\n2. В случае удовлетворения заявления о самоотводе или об отводе судьи, либо нескольких судей, либо всего состава суда дело рассматривается в том же арбитражном суде, но в ином составе судей.\n\n3. Если в результате удовлетворения самоотводов и отводов невозможно сформировать новый состав суда для рассмотрения данного дела в том же арбитражном суде, дело передается в другой арбитражный суд того же уровня в порядке, установленном статьей 39 настоящего Кодекса.\n\n(Обозначение и наименование параграфа исключены - Федеральный закон от 28.11.2018 № 451-ФЗ)","article_title":"Статья 26. Последствия удовлетворения заявления об отводе","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc084e56f4067ab0bdfe791e2548eafce2d2b8070527486b3ef9258f76ede208"},{"code_id":"APK_RF","article_number":"260","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба может быть подана в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. Апелляционная жалоба подписывается лицом, подающим жалобу, или его представителем, уполномоченным на подписание жалобы.\n\nАпелляционная жалоба, подаваемая в электронном виде, содержащая ходатайство об обеспечении иска, должна быть подписана усиленной квалифицированной электронной подписью.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В апелляционной жалобе должны быть указаны:\n\n1) наименование арбитражного суда, в который подается апелляционная жалоба;\n\n2) наименование лица, подающего жалобу, и других лиц, участвующих в деле;\n\n3) наименование арбитражного суда, принявшего обжалуемое решение, номер дела и дата принятия решения, предмет спора;\n\n4) требования лица, подающего жалобу, и основания, по которым лицо, подающее жалобу, обжалует решение, со ссылкой на законы, иные нормативные правовые акты, обстоятельства дела и имеющиеся в деле доказательства;\n\n5) перечень прилагаемых к жалобе документов.\n\nВ апелляционной жалобе могут быть указаны номера телефонов, факсов, адреса электронной почты и иные необходимые для рассмотрения дела сведения, а также заявлены имеющиеся ходатайства.\n\n3. Лицо, подающее апелляционную жалобу, обязано направить другим лицам, участвующим в деле, копии апелляционн\n\nой жалобы и прилагаемых к ней документов, которые у них отсутствуют, заказным письмом с уведомлением о вручении либо вручить их другим лицам, участвующим в деле, или их представителям лично под расписку.\n\nАпелляционная жалоба и прилагаемые к ней документы в электронном виде направляются лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n4. К апелляционной жалобе прилагаются:\n\n1) копия оспариваемого решения;\n\n2) документы, подтверждающие уплату государственной пошлины в установленных порядке и размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки ее уплаты или об уменьшении размера государственной пошлины;\n\n3) документ, подтверждающий направление или вручение другим лицам, участвующим в деле, копий апелляционной жалобы и документов, которые у них отсутствуют;\n\n4) доверенность или иной документ, подтверждающие полномочия на подписание апелляционной жалобы, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего апелляционную жалобу, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nК апелляционной жалобе на определение арбитражного суда о возвращении искового заявления должны быть также приложены возвращенное исковое заявление и документы, прилагавшиеся к нему при подаче в арбитражный суд. Документы, прилагаемые к апелляционной жалобе, могут быть представлены в арбитражный суд в электронном виде. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 260. Форма и содержание апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a49b8b70d002d355c4f8cde4ea0ebc463d2601f2017d1c363e0143885020c3c"},{"code_id":"APK_RF","article_number":"261","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба, поданная с соблюдением требований, предъявляемых настоящим Кодексом к ее форме и содержанию, принимается к производству арбитражного суда апелляционной инстанции. В случае нарушения указанных требований арбитражный суд или оставляет жалобу без движения, или возвращает ее в порядке, предусмотренном в статьях 263 и 264 настоящего Кодекса.\n\n2. Вопрос о принятии апелляционной жалобы к производству решается судьей арбитражного суда апелляционной инстанции единолично в пятидневный срок со дня ее поступления в арбитражный суд апелляционной инстанции.\n\nО принятии апелляционной жалобы арбитражный суд апелляционной инстанции выносит определение, которым возбуждается производство по апелляционной жалобе.\n\nВ определении указываются время и место проведения судебного заседания по рассмотрению апелляционной жалобы. При этом время проведения первого судебного заседания по рассмотрению апелляционной жалобы определяется с учетом того, что оно не может быть назначено ранее истечения срока, установленного настоящим Кодексом для обжалования соответствующего решения арбитражного суда. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 261. Принятие апелляционной жалобы к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c69256f7cf481c94f78b243c28ba5c03fa7e133bc931a788de20ebd7ed19648"},{"code_id":"APK_RF","article_number":"262","version_date":"2002-07-24","article_text":"1. Лицо, участвующее в деле, направляет отзыв на апелляционную жалобу с приложением документов, подтверждающих возражения относительно жалобы, другим лицам, участвующим в деле, и в арбитражный суд.\n\nК отзыву, направляемому в арбитражный суд, прилагается также документ, подтверждающий направление отзыва другим лицам, участвующим в деле.","article_title":"Статья 262. Отзыв на апелляционную жалобу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6ed791d69b5321994d73cfb1894535b2bf83aab45a02a9e999800cf0a21b8ce"},{"code_id":"APK_RF","article_number":"263","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции, установив при рассмотрении вопроса о принятии апелляционной жалобы к производству, что она подана с нарушением требований, установленных статьей 260 настоящего Кодекса, выносит определение об оставлении апелляционной жалобы без движения.\n\nАбзац. (Утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n2. В определении арбитражный суд указывает основания для оставления апелляционной жалобы без движения и срок, в течение которого лицо, подавшее апелляционную жалобу, должно устранить обстоятельства, послужившие основанием для оставления апелляционной жалобы без движения.\n\n3. Копия определения об оставлении апелляционной жалобы без движения направляется лицу, подавшему апелляционную жалобу, не позднее следующего дня после дня его вынесения.\n\n4. В случае, если обстоятельства, послужившие основанием для оставления апелляционной жалобы без движения, будут устранены в срок, указанный в определении суда, апелляционная жалоба считается поданной в день ее первоначального поступления в суд и принимается к производству арбитражного суда апелляционной инстанции.\n\n5. В случае, если указанные обстоятельства не будут устранены в срок, указанный в определении, арбитражный суд возвращает апелляционную жалобу и прилагаемые к ней документы лицу, подавшему жалобу, в порядке, установленном статьей 264 настоящего Кодекса.","article_title":"Статья 263. Оставление апелляционной жалобы без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c561e425eeb0b46389a46be9d644edd03ae2cdbf1e5b38f8c652bcc8a0c4dc6"},{"code_id":"APK_RF","article_number":"264","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции возвращает апелляционную жалобу, если при рассмотрении вопроса о принятии апелляционной жалобы к производству установит, что:\n\n1) апелляционная жалоба подана лицом, не имеющим права на обжалование судебного акта в порядке апелляционного производства;\n\n11) апелляционная жалоба не подписана или апелляционная жалоба подписана  лицом, не имеющим полномочий на ее подписание; (Дополнение пунктом - Федеральный закон от 28.11.2018 № 451-ФЗ) (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\n2) апелляционная жалоба подана на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке апелляционного производства;\n\n3) апелляционная жалоба подана по истечении срока подачи апелляционной жалобы, установленного в настоящем Кодексе, и не содержит ходатайство о его восстановлении или в восстановлении пропущенного срока на подачу апелляционной жалобы отказано;\n\n4) до вынесения определения о принятии апелляционной жалобы к производству суда от лица, подавшего жалобу, поступило ходатайство о ее возвращении;\n\n5) не устранены обстоятельства, послужившие основанием для оставления жалобы без движения, в срок, установленный в определении суда.\n\nАрбитражный суд апелляционной инстанции также возвращает жалобу, если отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины или об уменьшении ее размера.\n\n2. О возвращении апелляционной жалобы арбитражный суд выносит определение.\n\n3. В определении указываются основания для возвращения апелляционной жалобы, решается вопрос о возврате государственной пошлины из федерального бюджета.\n\nКопия определения о возвращении апелляционной жалобы направляется лицу, подавшему жалобу, вместе с жалобой и прилагаемыми документами не позднее следующего дня после дня его вынесения или после истечения срока, установленного судом для устранения обстоятельств, послуживших основанием для оставления апелляционной жалобы без движения.\n\n4. Определение арбитражного суда о возвращении апелляционной жалобы может быть обжаловано.\n\nВ случае отмены определения апелляционная жалоба считается поданной в день первоначального обращения в арбитражный суд.\n\n5. Возвращение апелляционной жалобы не препятствует повторному обращению с апелляционной жалобой в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для ее возвращения.","article_title":"Статья 264. Возвращение апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdd3aa9798701d56aab9d107dd33a54639707b68dc4d2aa2f8888cfd1bbcbd27"},{"code_id":"APK_RF","article_number":"265","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции прекращает производство по апелляционной жалобе, если от лица, ее подавшего, после принятия апелляционной жалобы к производству арбитражного суда поступило ходатайство об отказе от апелляционной жалобы и отказ был принят арбитражным судом в соответствии со статьей 49 настоящего Кодекса.\n\n2. В случае, если в апелляционной жалобе заявлены новые требования, которые не были предметом рассмотрения в арбитражном суде первой инстанции, принявшем обжалуемое решение, арбитражный суд апелляционной инстанции прекращает производство по апелляционной жалобе в части этих требований.\n\n3. О прекращении производства по апелляционной жалобе арбитражный суд выносит определение.\n\nКопии определения о прекращении производства по апелляционной жалобе направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения.\n\n4. Определение арбитражного суда о прекращении производства по апелляционной жалобе может быть обжаловано.\n\n5. В случае прекращения производства по апелляционной жалобе повторное обращение того же лица по тем же основаниям в арбитражный суд с апелляционной жалобой не допускается.","article_title":"Статья 265. Прекращение производства по апелляционной жалобе","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"edbb7abf24c376eef0b5bd522c949ecc4ba9c2ea06c8282cfb8d5cfccf3b6587"},{"code_id":"APK_RF","article_number":"265.1","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции по ходатайству лиц, участвующих в деле, вправе приостановить исполнение судебных актов, принятых арбитражным судом первой инстанции, при условии, если заявитель обосновал невозможность или затруднительность поворота исполнения либо предоставил обеспечение, предусмотренное в части 2 настоящей статьи.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. Исполнение решения арбитражного суда приостанавливается арбитражным судом апелляционной инстанции при предоставлении лицом, ходатайствующим о таком приостановлении, обеспечения возмещения другой стороне по делу возможных убытков (встречного обеспечения) путем внесения на депозитный счет арбитражного суда апелляционной инстанции денежных средств в размере оспариваемой суммы либо предоставления банковской гарантии, поручительства или иного финансового обеспечения на ту же сумму.\n\n3. О приостановлении исполнения судебного акта или об отказе в приостановлении исполнения арбитражный суд апелляционной инстанции выносит определение в трехдневный срок со дня поступления ходатайства в суд. Определение может быть обжаловано в арбитражный суд кассационной инстанции. Содержание этого определения может быть изложено в определении о принятии апелляционной жалобы к производству суда.\n\nКопия определения направляется лицам, участвующим в деле.\n\n4. Исполнение судебного акта приостанавливается на срок до принятия арбитражным судом апелляционной инстанции постановления по результатам рассмотрения апелляционной жалобы, если судом не установлен иной срок приостановления.\n\n(Дополнение статьей - Федеральный закон от 25.06.2012 № 86-ФЗ)","article_title":"Статья 265.1. Приостановление исполнения судебных актов арбитражным судом апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"146ba21e4ca650aefcf7cac50a0751cec3797ca857d1c774759d26aab00f0090"},{"code_id":"APK_RF","article_number":"267","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 30.04.2010 № 69-ФЗ)","article_title":"Статья 267. Срок рассмотрения апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3719fd3804ca9e264fffb5107da372c727e94e80dbaef9c4f409dfde93141e50"},{"code_id":"APK_RF","article_number":"268","version_date":"2002-07-24","article_text":"1. При рассмотрении дела в порядке апелляционного производства арбитражный суд по имеющимся в деле и дополнительно представленным доказательствам повторно рассматривает дело.\n\nДокументы, представленные для обоснования возражений относительно апелляционной жалобы в соответствии со статьей 262 настоящего Кодекса, принимаются и рассматриваются арбитражным судом апелляционной инстанции по существу.\n\nНа отмену решения арбитражного суда первой инстанции указывается в постановлении, принимаемом арбитражным судом апелляционной инстанции по результатам рассмотрения апелляционной жалобы. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n(Дополнение частью - Федеральный закон от 30.04.2010 № 69-ФЗ)","article_title":"Статья 268. Пределы рассмотрения дела арбитражным судом апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25f4cf609512a1ec1680c9e1a0f30b96046f2c7024bb9cbccff1bdb7252b19b4"},{"code_id":"APK_RF","article_number":"269","version_date":"2002-07-24","article_text":"По результатам рассмотрения апелляционной жалобы арбитражный суд апелляционной инстанции вправе:\n\n1) оставить решение арбитражного суда первой инстанции без изменения, а апелляционную жалобу - без удовлетворения;\n\n2) отменить или изменить решение суда первой инстанции полностью или в части и принять по делу новый судебный акт;\n\n3) отменить решение полностью или в части и прекратить производство по делу либо оставить исковое заявление без рассмотрения полностью или в части.","article_title":"Статья 269. Полномочия арбитражного суда апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bc533835f05450d62124807010094b838788e1215438d2936149a878c1772bf"},{"code_id":"APK_RF","article_number":"27","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n1) о несостоятельности (банкротстве);\n\n2) по спорам, указанным в статье 2251 настоящего Кодекса;\n\n3) по спорам об отказе в государственной регистрации, уклонении от государственной регистрации юридических лиц, индивидуальных предпринимателей;\n\n4) по спорам, вытекающим из деятельности депозитариев, связанной с учетом прав на акции и иные ценные бумаги и с осуществлением предусмотренных федеральным законом иных прав и обязанностей;\n\n5) по спорам, вытекающим из деятельности публично-правовых компаний, государственных компаний, государственных корпораций и связанным с их правовым положением, порядком управления ими, их созданием, реорганизацией, ликвидацией, организацией и с полномочиями их органов, ответственностью лиц, входящих в их органы;\n\n6) по спорам о защите интеллектуальных прав с участием организаций, осуществляющих коллективное управление авторскими и смежными правами, а также по спорам, отнесенным к подсудности Суда по интеллектуальным правам в соответствии с частью 4 статьи 34 настоящего Кодекса;\n\n7) о защите деловой репутации в сфере предпринимательской и иной экономической деятельности;\n\n71) по спорам, указанным в статье 2481 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 08.06.2020 № 171-ФЗ)\n\n8) другие дела, возникающие при осуществлении предпринимательской и иной экономической деятельности, в случаях, предусмотренных федеральным законом.\n\n(Дополнение частью - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 27. Споры, относящиеся к компетенции арбитражных судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"75a6172107a85f44042fe303739d3aa08eca6112946b87bd36495b2c9fa254c6"},{"code_id":"APK_RF","article_number":"270","version_date":"2002-07-24","article_text":"1. Основаниями для изменения или отмены решения арбитражного суда первой инстанции являются:\n\n1) неполное выяснение обстоятельств, имеющих значение для дела;\n\n2) недоказанность имеющих значение для дела обстоятельств, которые суд считал установленными;\n\n3) несоответствие выводов, изложенных в решении, обстоятельствам дела;\n\n4) нарушение или неправильное применение норм материального права или норм процессуального права.\n\n2. Неправильным применением норм материального права является:\n\n1) неприменение закона, подлежащего применению;\n\n2) применение закона, не подлежащего применению;\n\n3) неправильное истолкование закона.\n\n3. Нарушение или неправильное применение норм процессуального права является основанием для изменения или отмены решения арбитражного суда первой инстанции, если это нарушение привело или могло привести к принятию неправильного решения.\n\n4. Основаниями для отмены решения арбитражного суда первой инстанции в любом случае являются:\n\n1) рассмотрение дела арбитражным судом в незаконном составе;\n\n2) рассмотрение дела в отсутствие кого-либо из участвующих в деле лиц, не извещенных надлежащим образом о времени и месте судебного заседания;\n\n3) нарушение правил о языке при рассмотрении дела;\n\n4) принятие судом решения о правах и об обязан\n\nностях лиц, не привлеченных к участию в деле;\n\n5) неподписание решения судьей или одним из судей, если дело рассмотрено в коллегиальном составе судей, либо подписание решения не теми судьями, которые указаны в решении;\n\n6) отсутствие в деле протокола судебного заседания или подписание его не теми лицами, которые указаны в статье 155 настоящего Кодекса, в случае отсутствия аудиозаписи судебного заседания; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n7) нарушение правила о тайне совещания судей при принятии решения.","article_title":"Статья 270. Основания для изменения или отмены решения арбитражного суда первой инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4ced9babd807c20db39cbc9f36e634afae97159a9984c5b658c4d7957dc700b"},{"code_id":"APK_RF","article_number":"271","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения апелляционной жалобы арбитражный суд апелляционной инстанции принимает судебный акт, именуемый постановлением, которое подписывается судьями, рассматривавшими дело.\n\n2. В постановлении арбитражного суда апелляционной инстанции должны быть указаны:\n\n1) наименование арбитражного суда апелляционной инстанции, состав суда, принявшего постановление; фамилия лица, которое вело протокол судебного заседания;\n\n2) номер дела, дата и место принятия постановления;\n\n3) наименование лица, подавшего апелляционную жалобу, и его процессуальное положение;\n\n4) наименования лиц, участвующих в деле;\n\n5) предмет спора;\n\n6) фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий;\n\n7) дата принятия обжалуемого решения арбитражным судом первой инстанции; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n8) краткое изложение содержания принятого решения;\n\n9) основания, по которым в апелляционной жалобе заявлено требование о проверке законности и обоснованности решения;\n\n10) доводы, изложенные в отзыве на апелляционную жалобу;\n\n11) объяснения лиц, участвующих в деле и присутствующих в судебном заседании;\n\n12) обстоятельства дела, установленные арбитражным судом апелляционной инстанции; доказательства, на которых основаны выводы суда об этих обстоятельствах; законы и иные нормативные правовые акты, которыми руководствовался суд при принятии постановления; мотивы, по которым суд отклонил те или иные доказательства и не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле;\n\n13) мотивы, по которым суд апелляционной инстанции не согласился с выводами суда первой инстанции, если его решение было отменено полностью или в части;\n\n14) выводы о результатах рассмотрения апелляционной жалобы.\n\n3. В постановлении арбитражного суда апелляционной инстанции указывается на распределение между сторонами судебных расходов, в том числе судебных расходов, понесенных в связи с подачей апелляционной жалобы.\n\n4. Копии постановления арбитражного суда апелляционной инстанции направляются лицам, участвующим в деле, в пятидневный срок со дня принятия постановления.\n\n5. Постановление арбитражного суда апелляционной инстанции вступает в законную силу со дня его принятия.","article_title":"Статья 271. Постановление арбитражного суда апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"765c2b3fc08f85743a5837bf0feefb69c1e76cd0ce95078f1665f8383527ea7a"},{"code_id":"APK_RF","article_number":"272","version_date":"2002-07-24","article_text":"1. Определения арбитражного суда первой инстанции обжалуются в арбитражный суд апелляционной инстанции в соответствии со статьей 188 настоящего Кодекса.\n\nАпелляционные жалобы на определения арбитражного суда первой инстанции, за исключением случаев, предусмотренных настоящим Кодексом, рассматриваются судьей арбитражного суда апелляционной инстанции единолично. (Дополнение абзацем - Федеральный закон от 28.11.2018 № 451-ФЗ)\n\n1) оставить определение без изменения, жалобу без удовлетворения;\n\n2) отменить определение арбитражного суда первой инстанции и направить вопрос на новое рассмотрение в арбитражный суд первой инстанции;\n\n3) отменить определение полностью или в части и разрешить вопрос по существу.","article_title":"Статья 272. Апелляционные жалобы на определения арбитражного суда первой инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f1df7e839d3b34071457d709359a297698c97de3badca114b4cb8bb6eb3f6b28"},{"code_id":"APK_RF","article_number":"272.1","version_date":"2002-07-24","article_text":"(Дополнение статьей - Федеральный закон от 25.06.2012 № 86-ФЗ)\n\n(Наименование в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 272.1. Апелляционные жалобы на решения арбитражного суда по делам, рассмотренным в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ce764ba10aeb868bac600092ee988b5770e451adb23545ea1ce0f21eff006392"},{"code_id":"APK_RF","article_number":"273","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 273. Право кассационного обжалования","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dcb8aa602e92c57e5152bcb95c6af95dbb96cc7240b502c878aacb65ed6813c"},{"code_id":"APK_RF","article_number":"274","version_date":"2002-07-24","article_text":"1) дела, рассмотренные им в качестве суда первой инстанции;\n\n2) дела о защите интеллектуальных прав, рассмотренные арбитражными судами субъектов Российской Федерации в качестве суда первой инстанции, арбитражными апелляционными судами.\n\n(Дополнение частью - Федеральный закон от 08.12.2011 № 422-ФЗ)","article_title":"Статья 274. Арбитражный суд кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4ab952abacd7259cecec12b08b808dc821a29f63a57d24c5f256ca9f5e3bf24"},{"code_id":"APK_RF","article_number":"275","version_date":"2002-07-24","article_text":"1. Кассационная жалоба подается в арбитражный суд кассационной инстанции, полномочный ее рассматривать, через арбитражный суд, принявший решение.\n\n2. Арбитражный суд, принявший решение, обязан направить кассационную жалобу вместе с делом в соответствующий арбитражный суд кассационной инстанции в трехдневный срок со дня поступления жалобы в суд.","article_title":"Статья 275. Порядок подачи кассационной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6d782fe693200933bae8194736ea988b2f1c59115b5f080849c7b7b0c4ec74cf"},{"code_id":"APK_RF","article_number":"277","version_date":"2002-07-24","article_text":"1. Кассационная жалоба подается в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. Кассационная жалоба подписывается лицом, подающим жалобу, или его представителем, уполномоченным на подписание жалобы.\n\nКассационная жалоба, подаваемая в электронном виде, содержащая ходатайство об обеспечении иска, должна быть подписана усиленной квалифицированной электронной подписью.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В кассационной жалобе должны быть указаны:\n\n1) наименование арбитражного суда, в который подается кассационная жалоба;\n\n2) наименования лица, подающего жалобу, с указанием его процессуального положения, а также других лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) наименование арбитражного суда, принявшего обжалуемое решение, постановление, номер дела и дата принятия решения, постановления, предмет спора;\n\n4) требования лица, подающего жалобу, о проверке законности обжалуемого судебного акта и основания, по которым лицо, подающее жалобу, обжалует решение, постановление, со ссылкой на законы или иные нормативные правовые акты, обстоятельства дела и имеющиеся в деле доказательства;\n\n5) перечень прилагаемых к жалобе документов.\n\nВ кассационной жалобе могут быть также указаны номера телефонов, факсов, адреса электронной почты и иные необходимые для рассмотрения дела сведения, заявлены имеющиеся ходатайства.\n\n3. Лицо, подающее кассационную жалобу, обязано направить другим лицам, участвующим в деле, копии кассационной жалобы и прилагаемых к ней документов, которые у них отсутствуют, заказным письмом с уведомлением о вручении либо вручить их другим участвующим в деле лицам или их представителям лично под расписку.\n\nКассационная жалоба и прилагаемые к ней документы в электронном виде направляются лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n4. К кассационной жалобе прилагаются:\n\n1) копия обжалуемого судебного акта;\n\n2) документы, подтверждающие уплату государственной пошлины в установленных порядке и размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера;\n\n3) документы, подтверждающие направление или вручение другим лицам, участвующим в деле, копий кассационной жалобы и документов, которые у них отсутствуют;\n\n4) доверенность или иной документ, подтверждающие полномочия на подписание кассационной жалобы, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего кассационную жалобу, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)","article_title":"Статья 277. Форма и содержание кассационной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"846dc2a0840f82e7b684961501592f769161e24a47dbc9b595de1a4c4a9476a0"},{"code_id":"APK_RF","article_number":"278","version_date":"2002-07-24","article_text":"1. Кассационная жалоба, поданная с соблюдением требований, предъявляемых настоящим Кодексом к ее форме и содержанию, принимается к производству арбитражного суда кассационной инстанции. В случае нарушения указанных требований арбитражный суд кассационной инстанции или оставляет кассационную жалобу без движения, или возвращает кассационную жалобу в порядке, предусмотренном статьями 280, 281 настоящего Кодекса.\n\n2. Вопрос о принятии кассационной жалобы к производству арбитражного суда кассационной инстанции решается судьей единолично в пятидневный срок со дня ее поступления в арбитражный суд кассационной инстанции.\n\n3. О принятии кассационной жалобы к производству арбитражный суд выносит определение, которым возбуждается производство по кассационной жалобе.\n\nВ определении указываются время и место проведения судебного заседания по рассмотрению кассационной жалобы. При этом время проведения первого судебного заседания по рассмотрению кассационной жалобы определяется с учетом того, что оно не может быть назначено ранее истечения срока, установленного настоящим Кодексом для подачи кассационной жалобы. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nКопии определения о принятии кассационной жалобы направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения.","article_title":"Статья 278. Принятие кассационной жалобы к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"db1b052ac750d31835e4be6025892a98c7bbecc5312ccb717634ad2472bdb06d"},{"code_id":"APK_RF","article_number":"279","version_date":"2002-07-24","article_text":"1. Лицо, участвующее в деле, направляет отзыв на кассационную жалобу с приложением документов, подтверждающих возражения относительно жалобы, другим лицам, участвующим в деле, и в арбитражный суд.\n\nК отзыву, направляемому в арбитражный суд, прилагается также документ, подтверждающий направление отзыва другим лицам, участвующим в деле.","article_title":"Статья 279. Отзыв на кассационную жалобу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"66b9e12bcfaafe3e3315d18afe652ef9799346ff8537e1e221953f17bb16c0ff"},{"code_id":"APK_RF","article_number":"28","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nАрбитражные суды рассматривают в порядке искового производства возникающие из гражданских правоотношений экономические споры и другие дела, связанные с осуществлением предпринимательской и иной экономической деятельности юридическими лицами и индивидуальными предпринимателями, а в случаях, предусмотренных настоящим Кодексом и иными федеральными законами, другими организациями и гражданами, за исключением дел, рассматриваемых Московским городским судом в соответствии с частью третьей статьи 26 Гражданского процессуального кодекса Российской Федерации. (В редакции Федерального закона от 02.07.2013 № 187-ФЗ)","article_title":"Статья 28. Компетенция арбитражных судов по экономическим спорам и иным делам, возникающим из гражданских правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04fb60024458f2defcfb5a4a8f478a1187c0ffdc3d88033d692d2d65ba47bbea"},{"code_id":"APK_RF","article_number":"280","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции, установив при рассмотрении вопроса о принятии кассационной жалобы к производству, что она подана с нарушением требований, установленных статьей 277 настоящего Кодекса, выносит определение об оставлении кассационной жалобы без движения.\n\n2. В определении арбитражный суд указывает основания оставления кассационной жалобы без движения и срок, в течение которого лицо, подавшее кассационную жалобу, должно устранить обстоятельства, послужившие основанием для оставления кассационной жалобы без движения.\n\n3. Копия определения об оставлении кассационной жалобы без движения направляется лицу, подавшему кассационную жалобу, не позднее следующего дня после дня его вынесения.\n\n4. В случае, если обстоятельства, послужившие основанием для оставления кассационной жалобы без движения, будут устранены в срок, указанный в определении суда, кассационная жалоба считается поданной в день ее первоначального поступления в суд и принимается к производству арбитражного суда кассационной инстанции.\n\n5. В случае, если указанные обстоятельства не будут устранены в срок, установленный в определении, арбитражный суд возвращает кассационную жалобу и прилагаемые к ней документы лицу, подавшему жалобу, в порядке, установленном статьей 281 настоящего Кодекса.","article_title":"Статья 280. Оставление кассационной жалобы без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00d1744eb1c358332e6d2a6a02e4664fa4eaf1d1405f925bd374d2d4eb5c02e2"},{"code_id":"APK_RF","article_number":"281","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции возвращает кассационную жалобу, если при рассмотрении вопроса о принятии кассационной жалобы к производству установит, что:\n\n1) кассационная жалоба подана лицом, не имеющим права на обжалование судебного акта в порядке кассационного производства, или подана на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке кассационного производства;\n\n>11) кассационная жалоба не подписана или кассационная жалоба подписана  лицом, не имеющим полномочий на ее подписание; (Дополнение пунктом - Федеральный закон от 28.11.2018 № 451-ФЗ) (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\n2) кассационная жалоба подана по истечении срока подачи кассационной жалобы, установленного настоящим Кодексом, и не содержит ходатайство о его восстановлении или в восстановлении пропущенного срока отказано;\n\n3) до вынесения определения о принятии кассационной жалобы к производству арбитражного суда кассационной инстанции от лица, подавшего кассационную жалобу, поступило ходатайство о ее возвращении;\n\n4) не устранены обстоятельства, послужившие основанием для оставления кассационной жалобы без движения, в срок, установленный в определении суда;\n\n5) кассационная жалоба подана на судебный акт, который не был обжалован в арбитражный суд апелляционной инстанции, если иное не предусмотрено настоящим Кодексом. (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\nАрбитражный суд кассационной инстанции также возвращает кассационную жалобу, если отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера.\n\n2. О возвращении кассационной жалобы арбитражный суд выносит определение.\n\nКопия определения о возвращении кассационной жалобы направляется лицу, подавшему ее, вместе с кассационной жалобой и прилагаемыми к ней документами не позднее следующего дня после дня его вынесения или после истечения срока, установленного судом для устранения обстоятельств, послуживших основанием для оставления кассационной жалобы без движения.\n\n3. Определение о возвращении кассационной жалобы может быть обжаловано в арбитражный суд кассационной инстанции в порядке, установленном статьей 291 настоящего Кодекса.\n\nВ случае отмены определения кассационная жалоба считается поданной в день первоначального обращения в арбитражный суд.\n\n4. Возвращение кассационной жалобы не препятствует повторному обращению с кассационной жалобой в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для ее возвращения.","article_title":"Статья 281. Возвращение кассационной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b8c2226bc4028c5d51fc154c0b13bb3bd960ee02b1a2d4c747bd12b0fe41d0d"},{"code_id":"APK_RF","article_number":"282","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции прекращает производство по кассационной жалобе, если после принятия кассационной жалобы к производству суда от лица, ее подавшего, поступило ходатайство об отказе от кассационной жалобы и отказ принят судом в соответствии со статьей 49 настоящего Кодекса.\n\n2. О прекращении производства по кассационной жалобе арбитражный суд выносит определение.\n\nВ определении могут быть разрешены вопросы о распределении между сторонами судебных расходов, о возврате государственной пошлины из федерального бюджета.\n\nКопии определения о прекращении производства по кассационной жалобе направляются лицам, участвующим в деле.\n\n3. В случае прекращения производства по кассационной жалобе повторное обращение того же лица по тем же основаниям в арбитражный суд с кассационной жалобой не допускается.\n\n4. Определение арбитражного суда о прекращении производства по кассационной жалобе может быть обжаловано в арбитражный суд кассационной инстанции в порядке, установленном в статье 291 настоящего Кодекса.","article_title":"Статья 282. Прекращение производства по кассационной жалобе","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"31a310e6a5b521443a3f06e49c39398330916be3f1b1848ae8581e460a57c1d8"},{"code_id":"APK_RF","article_number":"283","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции вправе по ходатайству лиц, участвующих в деле, приостановить исполнение судебных актов, принятых арбитражным судом первой и апелляционной инстанций, при условии, если заявитель обосновал невозможность или затруднительность поворота исполнения либо предоставил обеспечение, предусмотренное в части 2 настоящей статьи.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. Исполнение решения, постановления арбитражного суда приостанавливается арбитражным судом кассационной инстанции при предоставлении лицом, ходатайствующим о таком приостановлении, обеспечения возмещения другой стороне по делу возможных убытков (встречного обеспечения) путем внесения на депозитный счет арбитражного суда кассационной инстанции денежных средств в размере оспариваемой суммы либо предоставления банковской гарантии, поручительства или иного финансового обеспечения на ту же сумму.\n\n3. О приостановлении исполнения судебного акта или об отказе в приостановлении исполнения арбитражный суд кассационной инстанции выносит определение в трехдневный срок со дня поступления ходатайства в суд. Определение может быть обжаловано в арбитражный суд кассационной инстанции. Содержание этого определения может быть изложено в определении о принятии кассационной жалобы к производству суда.\n\nКопия определения направляется лицам, участвующим в деле.\n\n4. Исполнение судебного акта приостанавливается на срок до принятия арбитражным судом кассационной инстанции постановления по результатам рассмотрения кассационной жалобы, если судом не установлен иной срок приостановления.","article_title":"Статья 283. Приостановление исполнения судебных актов арбитражным судом кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1b4aba32726428bce9e796c5a75d0857f713f8ae0e639ccb324361b0b2830265"},{"code_id":"APK_RF","article_number":"285","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 30.04.2010 № 69-ФЗ)","article_title":"Статья 285. Срок рассмотрения кассационной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3719fd3804ca9e264fffb5107da372c727e94e80dbaef9c4f409dfde93141e50"},{"code_id":"APK_RF","article_number":"286","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции проверяет законность решений, постановлений, принятых арбитражным судом первой и апелляционной инстанций, устанавливая правильность применения норм материального права и норм процессуального права при рассмотрении дела и принятии обжалуемого судебного акта и исходя из доводов, содержащихся в кассационной жалобе и возражениях относительно жалобы, если иное не предусмотрено настоящим Кодексом.\n\n2. Независимо от доводов, содержащихся в кассационной жалобе, арбитражный суд кассационной инстанции проверяет, не нарушены ли арбитражным судом первой и апелляционной инстанций нормы процессуального права, являющиеся в соответствии с частью 4 статьи 288 настоящего Кодекса основанием для отмены решения арбитражного суда первой инстанции, постановления арбитражного суда апелляционной инстанции.\n\n3. При рассмотрении дела арбитражный суд кассационной инстанции проверяет, соответствуют ли выводы арбитражного суда первой и апелляционной инстанций о применении нормы права установленным ими по делу обстоятельствам и имеющимся в деле доказательствам.","article_title":"Статья 286. Пределы рассмотрения дела в арбитражном суде кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"65258f1783ba605e5760d81232499d122ba32a7b121ecd71cb591ff9d62436b4"},{"code_id":"APK_RF","article_number":"287","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения кассационной жалобы арбитражный суд кассационной инстанции вправе:\n\n1) оставить решение арбитражного суда первой инстанции и (или) постановление суда апелляционной инстанции без изменения, а кассационную жалобу без удовлетворения;\n\n2) отменить или изменить решение суда первой инстанции и (или) постановление суда апелляционной инстанции полностью или в части и, не передавая дело на новое рассмотрение, принять новый судебный акт, если фактические обстоятельства, имеющие значение для дела, установлены арбитражным судом первой и апелляционной инстанций на основании полного и всестороннего исследования имеющихся в деле доказательств, но этим судом неправильно применена норма права либо законность решения, постановления арбитражного суда первой и апелляционной инстанций повторно проверяется арбитражным судом кассационной инстанции при отсутствии оснований, предусмотренных пунктом 3 части 1 настоящей статьи;\n\n3) отменить или изменить решение суда первой инстанции и (или) постановление суда апелляционной инстанции полностью или в части и направить дело на новое рассмотрение в соответствующий арбитражный суд, решение, постановление которого отменено или изменено, если этим судом нарушены нормы процессуального права, являющиеся в соответствии с частью 4 статьи 288 настоящего Кодекса основанием для отмены решения, постановления, или если выводы, содержащиеся в обжалуемых решении, постановлении, не соответствуют установленным по делу фактическим обстоятельствам или имеющимся в деле доказательствам. При направлении дела на новое рассмотрение суд может указать на необходимость рассмотрения дела коллегиальным составом судей и (или) в ином судебном составе;\n\n4) отменить или изменить решение суда первой инстанции и (или) постановление суда апелляционной инстанции полностью или в части и передать дело на рассмотрение другого арбитражного суда первой или апелляционной инстанции в пределах одного и того же судебного округа, если указанные судебные акты повторно проверяются арбитражным судом кассационной инстанции и содержащиеся в них выводы не соответствуют установленным по делу фактическим обстоятельствам или имеющимся в деле доказательствам;\n\n5) оставить в силе одно из ранее принятых по делу решений или постановлений;\n\n6) отменить решение суда первой инстанции и (или) постановление суда апелляционной инстанции полностью или в части и прекратить производство по делу либо оставить исковое заявление без рассмотрения полностью или в части.\n\n2. Арбитражный суд, рассматривающий дело в кассационной инстанции, не вправе устанавливать или считать доказанными обстоятельства, которые не были установлены в решении или постановлении либо были отвергнуты судом первой или апелляционной инстанции, предрешать вопросы о достоверности или недостоверности того или иного доказательства, преимуществе одних доказательств перед другими, о том, какая норма материального права должна быть применена и какое решение, постановление должно быть принято при новом рассмотрении дела.","article_title":"Статья 287. Полномочия арбитражного суда кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1efce6471deaa3cba4b35842192ffeb2facb8c4a02f1ffb6005e200b35e8fb0d"},{"code_id":"APK_RF","article_number":"288","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n1. Основаниями для изменения или отмены решения, постановления арбитражного суда первой и апелляционной инстанций являются несоответствие выводов суда, содержащихся в решении, постановлении, фактическим обстоятельствам дела, установленным арбитражным судом первой и апелляционной инстанций, и имеющимся в деле доказательствам, нарушение либо неправильное применение норм материального права или норм процессуального права.\n\n2. Неправильным применением норм материального права являются:\n\n1) неприменение закона, подлежащего применению;\n\n2) применение закона, не подлежащего применению;\n\n3) неправильное истолкование закона.\n\n3. Нарушение или неправильное применение норм процессуального права является основанием для изменения или отмены решения, постановления арбитражного суда, если это нарушение привело или могло привести к принятию неправильного решения, постановления.\n\n1) рассмотрение дела арбитражным судом в незаконном составе;\n\n2) рассмотрение дела в отсутствие кого-либо из лиц, участвующих в деле и не извещенных надлежащим образом о времени и месте судебного заседания;\n\n3) нарушение правил о языке при рассмотрении дела;\n\n4) принятие судом решения, постановления о правах и об обязанностях лиц, не привлеченных к участию в деле;\n\n5) неподписание решения, постановления судьей или одним из судей либо подписание решения, постановления не теми судьями, которые указаны в решении, постановлении;\n\n6) отсутствие в деле протокола судебного заседания или подписание его не теми лицами, которые указаны в статье 155 настоящего Кодекса, в случае отсутствия аудиозаписи судебного заседания; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n7) нарушение правила о тайне совещания судей при принятии решения, постановления.","article_title":"Статья 288. Основания для отмены судебного приказа, изменения или отмены решения, постановления арбитражного суда первой и апелляционной инстанций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"738dd506bcc71319ae7dee59ad7c282bd056fc090a1b206757c493e77c6ea297"},{"code_id":"APK_RF","article_number":"288.1","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу судебные приказы арбитражных судов первой инстанции могут быть обжалованы в порядке кассационного производства по правилам, предусмотренным настоящей главой, с учетом особенностей, установленных настоящей статьей.\n\n1) оставить судебный приказ без изменения, а кассационную жалобу без удовлетворения;\n\n2) (Пункт утратил силу - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n3) отменить судебный приказ и направить дело на новое рассмотрение, если имеются основания, указанные в части 4 настоящей статьи;\n\n4) (Пункт утратил силу - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n5) отменить судебный приказ, указав при этом в постановлении на право взыскателя предъявить требование в порядке искового производства или производства по делам, возникающим из административных и иных публичных правоотношений. (Дополнение пунктом - Федеральный закон от 19.12.2016 № 435-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 47-ФЗ)","article_title":"Статья 288.1. Особенности кассационного производства, связанные с пересмотром вступившего в законную силу судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed87378b1555923602e4d37c9dfae465c37c5302394e75b0651718be3a1880e7"},{"code_id":"APK_RF","article_number":"288.2","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу решения арбитражного суда первой инстанции и постановления арбитражного суда апелляционной инстанции, принятые по делам, рассмотренным в порядке упрощенного производства, могут быть обжалованы в порядке кассационного производства по правилам, предусмотренным настоящей главой, с учетом особенностей, установленных настоящей статьей.\n\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 45-ФЗ)","article_title":"Статья 288.2. Кассационные жалобы на решения арбитражного суда первой инстанции и постановления арбитражного суда апелляционной инстанции по делам, рассмотренным в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd606b71eb09e1a48b86f88b8ea0f9bf64501e69bb0bc079d4a934a5dfccf9a6"},{"code_id":"APK_RF","article_number":"289","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения кассационной жалобы арбитражный суд кассационной инстанции принимает судебный акт, именуемый постановлением, которое подписывается судьями, рассматривавшими дело.\n\n2. В постановлении арбитражного суда кассационной инстанции должны быть указаны:\n\n1) наименование арбитражного суда кассационной инстанции, состав суда, принявшего постановление;\n\n2) номер дела, дата и место принятия постановления;\n\n3) наименование лица, подавшего кассационную жалобу, его процессуальное положение;\n\n4) наименования лиц, участвующих в деле;\n\n5) предмет спора;\n\n6) фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий;\n\n7) наименования арбитражных судов, рассмотревших дело в первой и апелляционной инстанциях; дата принятия обжалуемых судебного приказа, решения, постановления; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n8) краткое изложение содержания принятых по делу решения, судебного приказа, постановления;\n\n9) основания, по которым в кассационной жалобе заявлены требования о проверке законности решения, судебного приказа, постановления;\n\n10) доводы, изложенные в отзыве на кассационную\n\n11) объяснения лиц, участвующих в деле и присутствовавших в судебном заседании;\n\n12) законы и иные нормативные правовые акты, которыми руководствовался суд кассационной инстанции при принятии постановления; мотивы принятого постановления; мотивы, по которым суд не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле;\n\n13) мотивы, по которым суд кассационной инстанции не согласился с выводами арбитражных судов первой и апелляционной инстанций, если их решение, судебный приказ, постановление были отменены полностью или в части;\n\n14) выводы по результатам рассмотрения кассационной жалобы;\n\n15) действия, которые должны быть выполнены лицами, участвующими в деле, и арбитражным судом первой или апелляционной инстанции, если дело передается на новое рассмотрение.\n\n(Часть в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n3. В постановлении арбитражного суда кассационной инстанции указывается на распределение между сторонами судебных расходов, понесенных в связи с подачей кассационной жалобы.\n\nПри отмене судебного акта с передачей дела на новое рассмотрение вопрос о распределении судебных расходов разрешается арбитражным судом, вновь рассматривающим дело.\n\n4. Копии постановления арбитражного суда кассационной инстанции направляются лицам, участвующим в деле, в пятидневный срок со дня принятия постановления.\n\n5. Постановление арбитражного суда кассационной инстанции вступает в законную силу со дня его принятия.","article_title":"Статья 289. Постановление арбитражного суда кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbdd7006b1a360e2972f84f5bc5c558816e8662321c79a809a8e244f1a0a32a9"},{"code_id":"APK_RF","article_number":"29","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n1) (Пункт утратил силу - Федеральный закон от 30.12.2012 № 317-ФЗ)\n\n11) об оспаривании нормативных правовых актов федеральных органов исполнительной власти, если рассмотрение таких дел в соответствии с настоящим Кодексом отнесено к компетенции Суда по интеллектуальным правам; (Дополнение пунктом - Федеральный закон от 30.12.2012 № 317-ФЗ) (В редакции Федерального закона от 28.06.2014 № 186-ФЗ)\n\n12) об оспаривании актов федеральных органов исполнительной власти, содержащих разъяснения законодательства и обладающих нормативными свойствами, если рассмотрение таких дел в соответствии с настоящим Кодексом отнесено к компетенции Суда по интеллектуальным правам; (Дополнение пунктом - Федеральный закон от 15.02.2016 № 18-ФЗ)\n\n2) об оспаривании затрагивающих права и законные интересы заявителя в сфере предпринимательской и иной экономической деятельности ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, организаций, наделенных федеральным законом отдельными государственными или иными публичными полномочиями, должностных лиц; (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n3) об административных правонарушениях, если федеральным законом их рассмотрение отнесено к компетенции арбитражного суда;\n\n4) о взыскании с организаций и граждан, осуществляющих предпринимательскую и иную экономическую деятельность, обязательных платежей, санкций, если федеральным законом не предусмотрен иной порядок их взыскания;\n\n5) другие дела, возникающие из административных и иных публичных правоотношений, если федеральным законом их рассмотрение отнесено к компетенции арбитражного суда.","article_title":"Статья 29. Компетенция арбитражных судов по экономическим спорам и другим делам, возникающим из административных и иных публичных правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"70cb7c06e52a922521b9597c7fc288d599a45d39e71d1916078a30d54e7a6fb2"},{"code_id":"APK_RF","article_number":"290","version_date":"2002-07-24","article_text":"1. Кассационные жалобы на определения арбитражного суда первой и апелляционной инстанций, поданные по правилам, установленным настоящим Кодексом, рассматриваются арбитражным судом кассационной инстанции в порядке, предусмотренном настоящей главой для рассмотрения кассационных жалоб на решения и постановления соответствующего арбитражного суда.\n\n2. Кассационные жалобы на определения арбитражного суда апелляционной инстанции о возвращении апелляционной жалобы и на другие препятствующие дальнейшему движению дела определения рассматриваются арбитражным судом кассационной инстанции в срок, не превышающий пятнадцати дней со дня поступления такой жалобы в арбитражный суд кассационной инстанции.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 290. Кассационные жалобы на определения арбитражного суда первой и апелляционной инстанций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bfc0ed08d7317d73ff510ab50ea25116c3a283b3327503045f5c5b7ca58d45ff"},{"code_id":"APK_RF","article_number":"291","version_date":"2002-07-24","article_text":"1. Жалобы на определение арбитражного суда кассационной инстанции о возвращении кассационной жалобы, поданные в арбитражный суд кассационной инстанции, вынесший такое определение, рассматриваются коллегиальным составом судей этого же суда в десятидневный срок со дня поступления жалобы в суд без извещения сторон.\n\n2. Жалобы на другие определения арбитражного суда кассационной инстанции, обжалование которых предусмотрено настоящим Кодексом, рассматриваются тем же арбитражным судом кассационной инстанции в ином судебном составе в порядке, предусмотренном настоящей главой.\n\n3. По результатам рассмотрения жалобы на определение арбитражного суда кассационной инстанции выносится определение.","article_title":"Статья 291. Жалобы на определение арбитражного суда кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88f9df6755102e12ec004449eca90b70cafbffed69ff53d5b25b5b7a1fdc03f8"},{"code_id":"APK_RF","article_number":"291.1","version_date":"2002-07-24","article_text":"1. Судебные акты могут быть полностью или в части обжалованы в Судебную коллегию Верховного Суда Российской Федерации в порядке кассационного производства лицами, участвующими в деле, а также иными лицами в случаях, предусмотренных настоящим Кодексом, если в оспариваемых судебных актах содержатся существенные нарушения норм материального права и (или) норм процессуального права, повлиявшие на исход судебного разбирательства и приведшие к нарушению их прав и законных интересов в сфере предпринимательской и иной экономической деятельности.\n\n2. Кассационные жалобы в Судебную коллегию Верховного Суда Российской Федерации подаются на вступившие в законную силу:\n\n1) решения и определения арбитражных судов республик, краев, областей, городов федерального значения, автономной области, автономных округов; постановления и определения арбитражных апелляционных судов; решения и определения арбитражных судов округов, принятые ими в первой инстанции; решения и определения Суда по интеллектуальным правам, принятые им в первой инстанции; определения арбитражных судов округов и Суда по интеллектуальным правам, вынесенные ими в процессе кассационного производства, если судебные акты, в отношении которых настоящим Кодексом предусмотрена возможность обжалования в порядке кассационного производства в арбитражный суд округа, обжаловались в указанном порядке; постановления и определения арбитражных судов округов и Суда по интеллектуальным правам, принятые по результатам рассмотрения кассационной жалобы (жалобы);\n\n2) судебные акты арбитражных судов, в отношении которых настоящим Кодексом возможность обжалования в порядке кассационного производства в арбитражный суд округа не предусмотрена, если они были предметом рассмотрения в арбитражном суде апелляционной инстанции, и постановление арбитражного суда апелляционной инстанции, принятое по данному делу.\n\n3. Постановления арбитражных судов округов, которыми не были отменены судебные приказы, отменены или изменены судебные акты, принятые в порядке упрощенного производства, не подлежат обжалованию в Судебную коллегию Верховного Суда Российской Федерации.\n\n4. Лицо, полагающее, что нарушено его право на судопроизводство в разумный срок, вправе подать в Судебную коллегию Верховного Суда Российской Федерации кассационную жалобу, в которой также могут быть изложены требования о присуждении ему компенсации.\n\n5. Генеральный прокурор Российской Федерации и заместители Генерального прокурора Российской Федерации вправе обратиться в Судебную коллегию Верховного Суда Российской Федерации с представлением о пересмотре в порядке кассационного производства вступивших в законную силу судебных актов, принятых по делам, участие прокурора в которых предусмотрено настоящим Кодексом.\n\n6. Кассационные жалоба, представление подаются непосредственно в Верховный Суд Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ) (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 291.1. Порядок подачи кассационных жалобы, представления в Судебную коллегию Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4cfe4a2b5d48ef70cd2b070e8cc04799122c57cd5cef3e58597ba6a330db29b"},{"code_id":"APK_RF","article_number":"291.10","version_date":"2002-07-24","article_text":"1. Суд направляет лицам, участвующим в деле, копии определения о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации и копии кассационных жалобы, представления. Время рассмотрения кассационных жалобы, представления вместе с делом в судебном заседании Судебной коллегии Верховного Суда Российской Федерации назначается с учетом того, чтобы лица, участвующие в деле, имели возможность явиться в судебное заседание.\n\n2. Лица, участвующие в деле, извещаются о времени и месте рассмотрения Судебной коллегией Верховного Суда Российской Федерации кассационных жалобы, представления вместе с делом. Неявка надлежащим образом извещенных лиц не препятствует рассмотрению кассационных жалобы, представления.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.10. Извещение лиц, участвующих в деле, о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"48b9bee935dbf1fa9d0a8f528575c59ce6f0f5c03e795019e39cbc89e3567391"},{"code_id":"APK_RF","article_number":"291.11","version_date":"2002-07-24","article_text":"1. Основаниями для отмены или изменения Судебной коллегией Верховного Суда Российской Федерации судебных актов в порядке кассационного производства являются существенные нарушения норм материального права и (или) норм процессуального права, которые повлияли на исход дела и без устранения которых невозможны восстановление и защита нарушенных прав, свобод, законных интересов в сфере предпринимательской и иной экономической деятельности, а также защита охраняемых законом публичных интересов.\n\n2. Основанием для присуждения Судебной коллегией Верховного Суда Российской Федерации компенсации за нарушение права на судопроизводство в разумный срок является нарушение права на судопроизводство в разумный срок по причинам, не зависящим от лица, обратившегося с требованием о присуждении компенсации.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.11. Основания для отмены или изменения Судебной коллегией Верховного Суда Российской Федерации судебных актов в порядке кассационного производства и присуждения компенсации за нарушение права на судопроизводство в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef67428a123bde332bb90f7f60bde1f6435decf6c299343d2ba60f39d05e6c5a"},{"code_id":"APK_RF","article_number":"291.12","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление вместе с делом рассматриваются в судебном заседании Судебной коллегии Верховного Суда Российской Федерации в срок, не превышающий двух месяцев со дня вынесения определения о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации.\n\n2. Рассматриваемые Судебной коллегией Верховного Суда Российской Федерации кассационные жалоба, представление вместе с делом докладываются судьей Верховного Суда Российской Федерации - докладчиком по данным жалобе, представлению.\n\n3. Судья-докладчик излагает обстоятельства дела, содержание судебных актов, принятых по делу, доводы, содержащиеся в кассационных жалобе, представлении, в том числе в кассационной жалобе, содержащей требование о присуждении компенсации за нарушение права на судопроизводство в разумный срок, и послужившие основанием для передачи кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации.\n\n4. В судебном заседании принимают участие лица, участвующие в деле, их представители, иные лица, подавшие кассационные жалобу, представление, если их права и законные интересы непосредственно затрагиваются обжалуемым судебным актом. Указанные лица могут участвовать в судебном заседании путем использования систем видеоконференц-связи в порядке, установленном статьей 1531 настоящего Кодекса.\n\n5. В случае, если прокурор является лицом, участвующим в рассмотрении дела, в судебном заседании Судебной коллегии Верховного Суда Российской Федерации по поручению Генерального прокурора Российской Федерации принимает участие должностное лицо органов прокуратуры.\n\n6. Лица, указанные в части 4 настоящей статьи и явившиеся в судебное заседание, вправе дать объяснения по делу. Первым дает объяснение лицо, подавшее кассационные жалобу, представление.\n\n7. Кассационная жалоба, содержащая требование о присуждении компенсации за нарушение права на судопроизводство в разумный срок, рассматривается по правилам, предусмотренным настоящей главой, и в соответствии с Федеральным законом от 30 апреля 2010 года № 68-ФЗ \"О компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок\".\n\n8. При решении вопроса о присуждении компенсации за нарушение права на судопроизводство в разумный срок Судебная коллегия Верховного Суда Российской Федерации в судебном заседании устанавливает факт нарушения права заявителя на судопроизводство в разумный срок, исходя из доводов, изложенных в кассационной жалобе, содержащей требование о присуждении указанной компенсации, содержания принятых по делу судебных актов, материалов дела и с учетом следующих обстоятельств:\n\n1) правовая и фактическая сложность дела;\n\n2) поведение заявителя и других участников арбитражного процесса;\n\n3) достаточность и эффективность действий суда или судьи, совершаемых в целях своевременного рассмотрения дела;\n\n4) общая продолжительность судопроизводства по делу.\n\n9. По результатам рассмотрения кассационных жалобы, представления вместе с делом Судебная коллегия Верховного Суда Российской Федерации выносит определение.\n\n10. Вопросы, возникающие при рассмотрении кассационных жалобы, представления вместе с делом в порядке кассационного производства, разрешаются судьями большинством голосов.\n\n11. По результатам рассмотрения кассационных жалобы, представления вместе с делом Судебная коллегия Верховного Суда Российской Федерации выносит определение и объявляет его по правилам, предусмотренным соответственно статьями 167 и 176 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.12. Срок и порядок рассмотрения кассационных жалобы, представления вместе с делом в судебном заседании Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5fdaf20c1d5f725756894c50a82b6b58800584c1fbec8d4ce52fb371ac4edcd"},{"code_id":"APK_RF","article_number":"291.13","version_date":"2002-07-24","article_text":"1. В определении Судебной коллегии Верховного Суда Российской Федерации, вынесенном по результатам рассмотрения кассационных жалобы, представления в порядке кассационного производства, должны быть указаны:\n\n1) наименование и состав суда, вынесшего определение;\n\n2) номер дела, дата и место вынесения определения;\n\n3) наименование лица, подавшего кассационные жалобу, представление о пересмотре дела в порядке кассационного производства, его процессуальное положение, адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) фамилия и инициалы судьи, вынесшего определение о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации;\n\n5) содержание обжалуемых судебных актов;\n\n6) фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий;\n\n7) наименования арбитражных судов, рассмотревших дело в первой, апелляционной и кассационной инстанциях; дата принятия обжалуемых решения, постановления, определения; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n8) объяснения лиц, участвующих в деле и присутствовавших в судебном заседании;\n\n9) законы и иные нормативные правовые акты, которыми руководствовалась Судебная коллегия Верховного Суда Российской Федерации при вынесении определения; мотивы вынесенного определения; мотивы, по которым суд не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле;\n\n10) мотивы, по которым Судебная коллегия Верховного Суда Российской Федерации не согласилась с выводами суда первой, апелляционной или кассационной инстанции, если его решение, постановление или определение было отменено полностью или в части;\n\n11) выводы по результатам рассмотрения кассационных жалобы, представления;\n\n12) основания для присуждения компенсации за нарушение права на судопроизводство в разумный срок или отказа в ее присуждении;\n\n13) размер компенсации за нарушение права на судопроизводство в разумный срок;\n\n14) действия, которые должны быть выполнены лицами, участвующими в деле, и арбитражным судом первой, апелляционной или кассационной инстанции, если дело передается на новое рассмотрение.\n\n2. Копии определения Судебной коллегии Верховного Суда Российской Федерации, вынесенного по результатам рассмотрения кассационных жалобы, представления вместе с делом, направляются лицам, участвующим в деле, в пятидневный срок со дня вынесения определения.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.13. Определение Судебной коллегии Верховного Суда Российской Федерации, вынесенное по результатам рассмотрения кассационных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d82239a647e23f89d91ff66da78f8840edc00c2e4600b1e84877b26a716b3f3"},{"code_id":"APK_RF","article_number":"291.14","version_date":"2002-07-24","article_text":"1. Судебная коллегия Верховного Суда Российской Федерации по результатам рассмотрения кассационных жалобы, представления вместе с делом вправе:\n\n1) оставить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции без изменения, кассационные жалобу, представление без удовлетворения;\n\n2) отменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции полностью либо в части и направить дело на новое рассмотрение в соответствующий арбитражный суд. При направлении дела на новое рассмотрение Судебная коллегия Верховного Суда Российской Федерации может указать на необходимость рассмотрения дела в ином составе судей;\n\n3) отменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции полностью либо в части и оставить заявление без рассмотрения или прекратить производство по делу;\n\n4) оставить в силе один из принятых по делу судебных актов;\n\n5) отменить либо изменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции и принять новый судебный акт, не передавая дело на новое рассмотрение, если допущена ошибка в применении и (или) толковании норм материального права;\n\n6) присудить компенсацию за нарушение права на судопроизводство в разумный срок или отказать в ее присуждении;\n\n7) оставить кассационные жалобу, представление без рассмотрения по существу при наличии оснований, предусмотренных статьей 2915 настоящего Кодекса.\n\n2. При рассмотрении дела в порядке кассационного производства Судебная коллегия Верховного Суда Российской Федерации проверяет правильность применения и (или) толкования норм материального права и (или) норм процессуального права арбитражными судами, рассматривавшими дело, в пределах доводов, изложенных в кассационных жалобе, представлении. В интересах законности Судебная коллегия Верховного Суда Российской Федерации вправе выйти за пределы доводов, изложенных в кассационных жалобе, представлении. При этом Судебная коллегия Верховного Суда Российской Федерации не вправе проверять законность судебных актов в той части, в которой они не обжалуются, а также законность судебных актов, которые не обжалуются.\n\n3. При рассмотрении дела в порядке кассационного производства Судебная коллегия Верховного Суда Российской Федерации не вправе устанавливать или считать доказанными обстоятельства, которые не были установлены либо были отвергнуты судом первой или апелляционной инстанции, либо предрешать вопросы о достоверности или недостоверности того или иного доказательства, преимуществе одних доказательств перед другими и определять, какой судебный акт должен быть принят при новом рассмотрении дела.\n\n4. Указания Судебной коллегии Верховного Суда Российской Федерации, в том числе на толкование закона, изложенные в определении об отмене судебного акта, обязательны для арбитражного суда, вновь рассматривающего дело.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.14. Полномочия Судебной коллегии Верховного Суда Российской Федерации по результатам рассмотрения кассационных жалобы, представления вместе с делом","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26b54f0c8a9796ddd4405fa36c6330d49fd8ce69cd75a051e1c3226ca66a8065"},{"code_id":"APK_RF","article_number":"291.15","version_date":"2002-07-24","article_text":"Определение Судебной коллегии Верховного Суда Российской Федерации, вынесенное по результатам рассмотрения кассационных жалобы, представления вместе с делом, вступает в законную силу со дня его вынесения.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.15. Вступление в законную силу определения Судебной коллегии Верховного Суда Российской Федерации, вынесенного по результатам рассмотрения кассационных жалобы, представления вместе с делом","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77ab39b9c8db83d7c919297a0a1cd19db3bf6a466b4a9cc6559f1796b9fe1a18"},{"code_id":"APK_RF","article_number":"291.16","version_date":"2002-07-24","article_text":"1. Кассационные жалобы, представления на судебные акты, принятые по делам, рассмотренным в порядке приказного производства, упрощенного производства, рассматриваются Судебной коллегией Верховного Суда Российской Федерации по правилам, предусмотренным настоящей главой, с учетом особенностей, установленных настоящей статьей.\n\n2. Кассационные жалобы, представления на судебные акты, принятые по делам, рассмотренным в порядке приказного производства, упрощенного производства, рассматриваются Судебной коллегией Верховного Суда Российской Федерации без вызова сторон. С учетом характера и сложности рассматриваемого вопроса, а также доводов кассационной жалобы и возражений относительно кассационной жалобы суд может вызвать лиц, участвующих в деле, в судебное заседание.\n\n(Дополнение статьей - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Глава утратила силу - Федеральный закон от 28.06.2014 № 186-ФЗ)\n\n(Дополнение главой - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.16. Особенности рассмотрения Судебной коллегией Верховного Суда Российской Федерации кассационных жалобы, представления на судебные акты, принятые по делам, рассмотренным в порядке приказного производства, упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f8822872a785e7f5d54a9c23460b1278adf66b8096bf2020c7235e359f3680f"},{"code_id":"APK_RF","article_number":"291.2","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление подаются в срок, не превышающий двух месяцев со дня вступления в силу последнего обжалуемого судебного акта, принятого по данному делу, если иное не предусмотрено настоящим Кодексом.\n\n2. Срок подачи кассационных жалобы, представления, пропущенный по причинам, не зависящим от лица, обратившегося с такими жалобой, представлением, в том числе в связи с отсутствием у него сведений об обжалуемом судебном акте, по ходатайству указанного лица может быть восстановлен судьей Судебной коллегии Верховного Суда Российской Федерации (далее - судья Верховного Суда Российской Федерации), рассматривающим кассационные жалобу, представление, при условии, что ходатайство подано не позднее шести месяцев со дня вступления в законную силу обжалуемого судебного акта или, если ходатайство подано одним из лиц, указанных в статье 42 настоящего Кодекса, со дня, когда это лицо узнало или должно было узнать о нарушении его прав и законных интересов обжалуемым судебным актом.\n\n3. Ходатайство о восстановлении пропущенного срока подачи кассационных жалобы, представления рассматривается судьей Верховного Суда Российской Федерации в порядке, предусмотренном статьей 117 настоящего Кодекса. По результатам рассмотрения данного ходатайства судья выносит определение о восстановлении пропущенного срока подачи кассационных жалобы, представления или об отказе в его восстановлении.\n\n4. Председатель Верховного Суда Российской Федерации, заместитель Председателя Верховного Суда Российской Федерации вправе не согласиться с определением судьи Верховного Суда Российской Федерации, указанным в части 3 настоящей статьи, и вынести определение об отказе в восстановлении пропущенного срока подачи кассационных жалобы, представления или о его восстановлении.\n\n5. До истечения срока, установленного настоящим Кодексом для подачи кассационных жалобы, представления, дело не может быть истребовано из арбитражного суда.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.2. Срок подачи кассационных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f0cc8ecc285abf02da2d6491725a613bd3f9b6d440c0b45c93e006ea716f3a2"},{"code_id":"APK_RF","article_number":"291.3","version_date":"2002-07-24","article_text":"1) наименование суда, в который подаются кассационные жалоба, представление;\n\n2) наименование лица, подающего кассационные жалобу, представление, его процессуальное положение;\n\n3) наименования лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) сведения об обжалуемом судебном акте и наименование принявшего его арбитражного суда, сведения о других судебных актах, принятых по делу, предмет спора;\n\n5) основания, по которым лицо, подающее кассационные жалобу, представление, обжалует судебный акт, с указанием на то, в чем заключаются существенные нарушения норм материального права и (или) норм процессуального права, повлиявшие на исход судебного разбирательства, и приведением доводов, свидетельствующих о существенных нарушениях прав и законных интересов лица в сфере предпринимательской и иной экономической деятельности;\n\n6) законы или иные нормативные правовые акты, подтверждающие, по мнению лица, наличие нарушений, указанных в пункте 5 настоящей части;\n\n7) просьба лица, подающего кассационные жалобу, представление;\n\n8) перечень документов, прилагаемых к кассационным жалобе, представлению.\n\n1) общая продолжительность судопроизводства по делу, исчисляемая со дня поступления искового заявления или заявления в арбитражный суд первой инстанции до дня принятия последнего судебного акта по делу;\n\n2) обстоятельства, известные лицу, подавшему кассационную жалобу, и повлиявшие на длительность судопроизводства по делу;\n\n3) доводы лица, подавшего кассационную жалобу, с указанием оснований для присуждения компенсации и ее размера;\n\n4) последствия нарушения права на судопроизводство в разумный срок и их значимость для лица, подавшего кассационную жалобу;\n\n5) реквизиты банковского счета лица, подавшего кассационную жалобу, на который должны быть перечислены средства, подлежащие взысканию.\n\n1) копии обжалуемого судебного акта и других судебных актов, принятых по делу, которые должны быть заверены соответствующим судом только в случае рассмотрения дела в закрытом судебном заседании; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n2) документы, подтверждающие уплату государственной пошлины в установленных порядке и размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера;\n\n3) доверенность или иной документ, подтверждающие полномочия на подписание кассационных жалобы, представления, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего кассационную жалобу, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.3. Форма и содержание кассационных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7f770f2570b53858f321a03e16586b604d565fa7fbd9e72414e5644ea0a0ce5"},{"code_id":"APK_RF","article_number":"291.4","version_date":"2002-07-24","article_text":"1. Лицо, участвующее в деле, получив копию кассационных жалобы, представления, направляет отзыв на кассационные жалобу, представление с приложением документов, подтверждающих возражения относительно жалобы, представления, другим лицам, участвующим в деле, и в Судебную коллегию Верховного Суда Российской Федерации.\n\n2. К отзыву, направляемому в Судебную коллегию Верховного Суда Российской Федерации, прилагается документ, подтверждающий направление отзыва другим лицам, участвующим в деле.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.4. Отзыв на кассационные жалобу, представление","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d6bca6ea4f9156d3694c1b6c4f4cc71939b6bd1a7fcc1e1d3d6e4f263767a0c"},{"code_id":"APK_RF","article_number":"291.5","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление возвращаются без рассмотрения по существу, если:\n\n1) кассационные жалоба, представление не отвечают требованиям, установленным частью 1, пунктами 1 - 4, 7 части 2, частями 5 и 7 статьи 2913 настоящего Кодекса;\n\n2) кассационные жалоба, представление поданы лицом, не имеющим права на обжалование судебного акта в порядке кассационного производства, или поданы на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке кассационного производства;\n\n3) кассационные жалоба, представление поданы по истечении срока, установленного частями 1 и 2 статьи 2912 настоящего Кодекса, и не содержат ходатайство о его восстановлении или в восстановлении пропущенного срока отказано;\n\n4) поступило ходатайство о возвращении или об отзыве кассационных жалобы, представления;\n\n5) кассационные жалоба, представление поданы с нарушением правил подсудности, установленных частью 2 статьи 2911 настоящего Кодекса. (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\n2. Кассационные жалоба, представление должны быть возвращены без рассмотрения по существу в течение десяти дней со дня их поступления в суд кассационной инстанции.\n\n3. Возвращение кассационных жалобы, представления не препятствует повторному обращению с кассационными жалобой, представлением после устранения обстоятельств, послуживших основанием для их возвращения.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.5. Возвращение кассационных жалобы, представления без рассмотрения по существу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88d5444980c142741f4a239cee4331ad2ccec0cbcc88d3bf8e95cba45e192a52"},{"code_id":"APK_RF","article_number":"291.6","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление, поданные в соответствии с правилами, установленными статьями 2911 - 2913 настоящего Кодекса, изучаются судьей Верховного Суда Российской Федерации.\n\n2. Судья Верховного Суда Российской Федерации изучает кассационные жалобу, представление по материалам, приложенным к ним, или по материалам истребованного дела.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n1) об отказе в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации, если изложенные в кассационных жалобе, представлении доводы не подтверждают существенных нарушений норм материального права и (или) норм процессуального права, повлиявших на исход дела, и не являются достаточным основанием для пересмотра судебных актов в кассационном порядке и (или) для решения вопроса о присуждении компенсации за нарушение права на судопроизводство в разумный срок, а также если указанные доводы не находят подтверждения в материалах дела. При этом кассационные жалоба, представление, а также копии обжалуемых судебных актов остаются в суде кассационной инстанции;\n\n2) о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации.\n\nмене данного определения и передаче кассационных жалобы, представления для рассмотрения в судебном заседании суда кассационной инстанции. Время рассмотрения этих жалобы, представления в Верховном Суде Российской Федерации при исчислении указанного срока не учитывается. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.6. Рассмотрение кассационных жалобы, представления в Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"92a719ea60b3867bb3ab455836e70b55531ee5fd3a924a1f40778885cb3488a9"},{"code_id":"APK_RF","article_number":"291.7","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление рассматриваются в Верховном Суде Российской Федерации в срок, не превышающий двух месяцев, если дело не было истребовано, и в срок, не превышающий трех месяцев, если дело было истребовано, не считая времени со дня истребования дела до дня его поступления в Верховный Суд Российской Федерации.\n\n2. Председатель Верховного Суда Российской Федерации, заместитель Председателя Верховного Суда Российской Федерации в случае истребования дела с учетом его сложности могут продлить срок рассмотрения кассационных жалобы, представления, но не более чем на два месяца.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.7. Срок рассмотрения кассационных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"211cb5e26a69e304bb76ff482b3d81659bfafb39c7356b3f63bdf133d567bace"},{"code_id":"APK_RF","article_number":"291.8","version_date":"2002-07-24","article_text":"В определении судьи Верховного Суда Российской Федерации об отказе в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) фамилия и инициалы судьи, вынесшего определение;\n\n3) наименование лица, подавшего кассационные жалобу, представление, его процессуальное положение, адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) сведения об обжалуемом судебном акте, дата его принятия и вступления в законную силу;\n\n5) мотивы отказа в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.8. Определение об отказе в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d153f62ac9fb1663d93fad91ebe133bf37884a4fcf951a7775493306d5024bc"},{"code_id":"APK_RF","article_number":"291.9","version_date":"2002-07-24","article_text":"В определении судьи Верховного Суда Российской Федерации о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) фамилия и инициалы судьи, вынесшего определение;\n\n3) наименование лица, подавшего кассационные жалобу, представление, его процессуальное положение, адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) сведения об обжалуемом судебном акте, дата его принятия и вступления в законную силу;\n\n5) содержание дела, по которому принят обжалуемый судебный акт;\n\n6) мотивированные основания передачи кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации и (или) для решения вопроса о присуждении компенсации за нарушение права на судопроизводство в разумный срок, а также общая продолжительность судопроизводства по делу.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.9. Определение о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4ddf2f926635ae84210f1221be2b46a70b413e393cdef8b5be439b136ed2920"},{"code_id":"APK_RF","article_number":"3","version_date":"2002-07-24","article_text":"1. В соответствии с Конституцией Российской Федерации законодательство о судопроизводстве в арбитражных судах находится в ведении Российской Федерации.\n\n2. Порядок судопроизводства в арбитражных судах определяется Конституцией Российской Федерации, Федеральным конституционным законом \"О судебной системе Российской Федерации\" и Федеральным конституционным законом \"Об арбитражных судах в Российской Федерации\", Арбитражным процессуальным кодексом Российской Федерации (далее - Кодекс) и принимаемыми в соответствии с ними другими федеральными законами.","article_title":"Статья 3. Законодательство о судопроизводстве в арбитражных судах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b8263b9f1b5c905c1ff07b3209b4a64943987cf3d5db7fca826ae8f74bc97ef"},{"code_id":"APK_RF","article_number":"30","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nАрбитражные суды рассматривают в порядке особого производства дела об установлении фактов, имеющих юридическое значение для возникновения, изменения и прекращения прав организаций и граждан в сфере предпринимательской и иной экономической деятельности.","article_title":"Статья 30. Компетенция арбитражных судов по делам об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3abaad70d114aae211172b4a4523756170fc36bc3714a9897f830256aa466431"},{"code_id":"APK_RF","article_number":"308.1","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу судебные акты, указанные в части 3 настоящей статьи, могут быть пересмотрены в порядке надзора Президиумом Верховного Суда Российской Федерации по надзорным жалобам лиц, участвующих в деле, и иных лиц, указанных в статье 42 настоящего Кодекса.\n\n2. Генеральный прокурор Российской Федерации, заместители Генерального прокурора Российской Федерации вправе обратиться в Президиум Верховного Суда Российской Федерации с представлением о пересмотре определений Судебной коллегии Верховного Суда Российской Федерации, вынесенных в порядке кассационного производства по делам, указанным в части 1 статьи 52 настоящего Кодекса.\n\n3. В Президиум Верховного Суда Российской Федерации обжалуются:\n\nившие в законную силу решения и определения Судебной коллегии Верховного Суда Российской Федерации, принятые по первой инстанции, если указанные решения и определения были предметом апелляционного рассмотрения;\n\n2) определения Апелляционной коллегии Верховного Суда Российской Федерации, вынесенные по результатам рассмотрения апелляционных жалоб, представлений на решения или определения Судебной коллегии Верховного Суда Российской Федерации, принятые по первой инстанции;\n\n3) определения Судебной коллегии Верховного Суда Российской Федерации, вынесенные в порядке кассационного производства.\n\n4. Надзорные жалоба, представление на судебные акты, принятые по делам, указанным в части 3 настоящей статьи, подаются в Верховный Суд Российской Федерации в срок, не превышающий трех месяцев со дня их вступления в законную силу.\n\n5. Срок подачи надзорных жалобы, представления о пересмотре судебного акта в порядке надзора, пропущенный по причинам, не зависящим от лица, обратившегося с такими заявлением или представлением, в том числе в связи с отсутствием у него сведений об обжалуемом судебном акте, по ходатайству заинтересованного лица может быть восстановлен судьей Верховного Суда Российской Федерации при условии, что ходатайство подано не позднее чем через шесть месяцев со дня вступления в законную силу последнего оспариваемого судебного акта или, если ходатайство подано лицом, указанным в статье 42 настоящего Кодекса, со дня, когда это лицо узнало или должно было узнать о нарушении его прав или законных интересов обжалуемым судебным актом.\n\nПо результатам рассмотрения ходатайства о восстановлении пропущенного срока подачи надзорных жалобы, представления судья выносит определение об отказе в восстановлении пропущенного срока подачи надзорных жалобы, представления или о его восстановлении. (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)","article_title":"Статья 308.1. Пересмотр судебных актов в порядке надзора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58d6e9796d5823bac53f1de82acb80a82e754d7f95d59b6c847271a1f509a791"},{"code_id":"APK_RF","article_number":"308.10","version_date":"2002-07-24","article_text":"1. Председатель Верховного Суда Российской Федерации или заместитель Председателя Верховного Суда Российской Федерации по жалобе заинтересованных лиц вправе внести в Президиум Верховного Суда Российской Федерации представление о пересмотре судебных постановлений в порядке надзора в целях устранения фундаментальных нарушений норм материального права и (или) норм процессуального права, которые повлияли на законность обжалуемых судебных постановлений и лишили участников спорных материальных или процессуальных правоотношений возможности осуществления прав, гарантированных настоящим Кодексом, в том числе права на доступ к правосудию, права на справедливое судебное разбирательство на основе принципа состязательности и равноправия сторон, либо существенно ограничили эти права.\n\n2. Дело по представлению Председателя Верховного Суда Российской Федерации или заместителя Председателя Верховного Суда Российской Федерации рассматривается Президиумом Верховного Суда Российской Федерации в порядке, предусмотренном статьей 3089 настоящего Кодекса.\n\n3. Председатель Верховного Суда Российской Федерации или заместитель Председателя Верховного Суда Российской Федерации, внесшие представление, не могут участвовать в рассмотрении Президиумом Верховного Суда Российской Федерации дела, о пересмотре которого ими внесено представление.\n\n4. Жалоба, указанная в части 1 настоящей статьи, может быть подана в течение четырех месяцев со дня вступления обжалуемых судебных постановлений в законную силу.","article_title":"Статья 308.10. Пересмотр судебных постановлений в порядке надзора по представлению Председателя Верховного Суда Российской Федерации или заместителя Председателя Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04c50214e2f42b6f9d7e613e8bfb3150b1021b532c125602388aad643c396063"},{"code_id":"APK_RF","article_number":"308.11","version_date":"2002-07-24","article_text":"1. Президиум Верховного Суда Российской Федерации, рассмотрев надзорные жалобу, представление вместе с делом в порядке надзора, вправе:\n\n1) оставить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции без изменения, над\n\nзорные жалобу, представление без удовлетворения;\n\n2) отменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции полностью либо в части и направить дело на новое рассмотрение в соответствующий суд. При направлении дела на новое рассмотрение Президиум Верховного Суда Российской Федерации может указать на необходимость рассмотрения дела в ином составе судей;\n\n3) отменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции полностью либо в части и оставить заявление без рассмотрения либо прекратить производство по делу;\n\n4) оставить в силе один из принятых по делу судебных актов;\n\n5) отменить либо изменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции и принять новое судебное постановление, не передавая дело на новое рассмотрение, если допущена ошибка в применении и (или) толковании норм материального права;\n\n6) оставить надзорные жалобу, представление без рассмотрения по существу при наличии оснований, предусмотренных статьей 3083 настоящего Кодекса.\n\n2. При рассмотрении дела в порядке надзора Президиум Верховного Суда Российской Федерации проверяет правильность применения и (или) толкования норм материального права и (или) норм процессуального права судами, рассматривавшими дело, в пределах доводов, изложенных в надзорных жалобе, представлении. В интересах законности Президиум Верховного Суда Российской Федерации вправе выйти за пределы доводов, изложенных в надзорных жалобе, представлении. При этом Президиум Верховного Суда Российской Федерации не вправе проверять законность судебных актов в той части, в которой они не обжалуются, а также законность судебных актов, которые не обжалуются.\n\n3. При рассмотрении дела в порядке надзора Президиум Верховного Суда Российской Федерации не вправе устанавливать или считать доказанными обстоятельства, которые не были установлены либо были отвергнуты судом первой или апелляционной инстанции, либо предрешать вопросы о достоверности или недостоверности того или иного доказательства, преимуществе одних доказательств перед другими и определять, какое судебное постановление должно быть принято при новом рассмотрении дела.\n\n4. Постановление Президиума Верховного Суда Российской Федерации подписывается председательствующим в заседании Президиума Верховного Суда Российской Федерации.\n\n5. Указания Президиума Верховного Суда Российской Федерации, в том числе на толкование закона, изложенные в постановлении Президиума Верховного Суда Российской Федерации, являются обязательными для суда, вновь рассматривающего дело.","article_title":"Статья 308.11. Полномочия Президиума Верховного Суда Российской Федерации при пересмотре судебных постановлений в порядке надзора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdb1e16da34854ab0c71e18206821b71335120c8adf572b11d75622dff69c720"},{"code_id":"APK_RF","article_number":"308.12","version_date":"2002-07-24","article_text":"В постановлении Президиума Верховного Суда Российской Федерации должны быть указаны:\n\n1) наименование и состав суда, принявшего постановление;\n\n2) дата и место принятия постановления;\n\n3) дело, по которому принято постановление;\n\n4) наименование лица, подавшего надзорные жалобу, представление, его процессуальное положение, место нахождения или место жительства;\n\n5) фамилия и инициалы судьи, вынесшего определение о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации;\n\n6) содержание обжалуемых судебных актов;\n\n7) выводы Президиума Верховного Суда Российской Федерации по результатам рассмотрения надзорных жалобы, представления;\n\n8) мотивы, по которым Президиум Верховного Суда Российской Федерации пришел к своим выводам, со ссылкой на законы, которыми он руководствовался при принятии постановления.","article_title":"Статья 308.12. Содержание постановления Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1b162d2a360ed115cf1f2d2137942a38070a51ad73dc1998e5f8b3e8f688d71"},{"code_id":"APK_RF","article_number":"308.13","version_date":"2002-07-24","article_text":"Постановление Президиума Верховного Суда Российской Федерации вступает в законную силу со дня его принятия и обжалованию не подлежит.\n\n(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 308.13. Вступление в законную силу постановления Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d001d61823cb4e9a077b4c3910dc4420e2b794299c5c39f12034f72b64ecca18"},{"code_id":"APK_RF","article_number":"308.2","version_date":"2002-07-24","article_text":"1. В надзорных жалобе, представлении должны быть указаны:\n\n1) наименование суда, в который они подаются;\n\n2) наименование лица, подающего надзорные жалобу, представление, его процессуальное положение, адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) наименования лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) наименования судов, рассматривавших дело в первой, апелляционной или кассационной инстанции, и содержание принятых ими судебных актов;\n\n5) сведения об обжалуемом судебном акте, дате его принятия и вступления в законную силу;\n\n6) предмет спора;\n\n7) основания пересмотра судебного акта в порядке надзора, предусмотренные статьей 3088 настоящего Кодекса, с приведением доводов, свидетельствующих о наличии таких оснований;\n\n8) просьба лица, подающего жалобу, представление;\n\n9) перечень документов, прилагаемых к заявлению или представлению.\n\n2. В надзорной жалобе лица, не принимавшего участия в деле, должно быть указано, какие права, свободы или законные интересы этого лица нарушены вступившим в законную силу судебным актом.\n\nДокументы, прилагаемые к надзорным жалобе, представлению, могут быть представлены в Верховный Суд Российской Федерации в электронном виде.","article_title":"Статья 308.2. Содержание надзорных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dee5618bf76f53ae2959f456ab42131f348186cd988816791ac2520009700277"},{"code_id":"APK_RF","article_number":"308.3","version_date":"2002-07-24","article_text":"1. Надзорные жалоба, представление возвращаются без рассмотрения по существу, если:\n\n1) надзорные жалоба, представление не отвечают требованиям, предусмотренным пунктами 1 - 6 и 8 части 1 и частями 3 - 5 статьи 3082 настоящего Кодекса;\n\n2) надзорные жалоба, представление поданы лицом, не имеющим права на обращение в суд надзорной инстанции, или поданы на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке надзора; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) пропущен срок обжалования судебного акта в порядке надзора, установленный частью 4 статьи 3081 настоящего Кодекса, и в надзорных жалобе, представлении не содержится ходатайство о его восстановлении или в восстановлении пропущенного срока отказано;\n\n4) поступила просьба о возвращении или об отзыве надзорных жалобы, представления;\n\n5) надзорные жалоба, представление поданы с нарушением правил подсудности, установленных частью 3 статьи 3081 настоящего Кодекса. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2. Надзорные жалоба, представление должны быть возвращены без рассмотрения по существу в течение десяти дней со дня их поступления в суд надзорной инстанции.","article_title":"Статья 308.3. Возвращение надзорных жалобы, представления без рассмотрения по существу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8bdec9a2f369352182dbb8b6e565788dffbe9b1f7fc1df7a1e3972d7ef252e0"},{"code_id":"APK_RF","article_number":"308.4","version_date":"2002-07-24","article_text":"1. Надзорные жалоба, представление, поданные в соответствии с правилами, установленными статьями 3081 и 3082 настоящего Кодекса, изучаются судьей Верховного Суда Российской Федерации.\n\n2. Судья Верховного Суда Российской Федерации изучает надзорные жалобу, представление по материалам, приложенным к ним, либо по материалам истребованного дела.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n1) об отказе в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации, если отсутствуют основания для пересмотра судебных постановлений в порядке надзора. При этом надзорные жалоба, представление, а также копии обжалуемых судебных постановлений остаются в суде надзорной инстанции;\n\n2) о передаче надзорных жалобы, представления вместе с делом для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации.","article_title":"Статья 308.4. Рассмотрение надзорных жалобы, представления в Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f79a76688e338d603e8e6d7881989ef8addcc1899e9378d04e4f48e537989c5"},{"code_id":"APK_RF","article_number":"308.5","version_date":"2002-07-24","article_text":"1. Надзорные жалоба, представление рассматриваются в Верховном Суде Российской Федерации в срок, не превышающий двух месяцев, если дело не было истребовано, и в срок, не превышающий трех месяцев, если дело было истребовано, не считая времени со дня истребования дела до дня его поступления в Верховный Суд Российской Федерации.\n\n2. Председатель Верховного Суда Российской Федерации, заместитель Председателя Верховного Суда Российской Федерации в случае истребования дела с учетом его сложности могут продлить срок рассмотрения надзорных жалобы, представления, но не более чем на два месяца.","article_title":"Статья 308.5. Срок рассмотрения надзорных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"99ebe1882f38996eee124c7e509fc79af3ebfbb06d0c2dff88269181af3db7f7"},{"code_id":"APK_RF","article_number":"308.6","version_date":"2002-07-24","article_text":"В определении судьи Верховного Суда Российской Федерации об отказе в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) фамилия и инициалы судьи, вынесшего определение;\n\n3) наименование лица, подавшего надзорные жалобу, представление, его процессуальное положение, место нахождения или место жительства;\n\n4) сведения об обжалуемом судебном акте, дата его принятия и вступления в законную силу;\n\n5) мотивы, по которым отказано в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации.","article_title":"Статья 308.6. Определение об отказе в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fefe651e07d7adad03b76fd5a585e5e76ca71ed9d34a51b1ab1adf77cdf7ebc0"}]$law7v003$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
